quests[38384] = { id = 38384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Natur", description = "Was für eine bösartige Kraft ist das?!\n\nEin Fluch, der stark genug ist, einen Halbgott zu lähmen? Das ist unvorstellbar!\n\nSchnell, {name}, Ihr müsst die Erzdruiden des Waldes versammeln. Mit ihrer Hilfe können wir Ysera herbeirufen. Sie wird sicher wissen, was meinen Mentor so peinigt.\n\nIch werde hierbleiben und Cenarius so gut ich kann helfen.\n\nKehrt nach Lorlathil zurück und sprecht mit Aranelle. Sie weiß, wo sich die Erzdruiden aufhalten.\n\nUnd bitte beeilt Euch...", sourceObjective = "Sprecht mit Aranelle in Lorlathil.", completion = "Cenarius braucht Hilfe? Herr des Waldes, wir werden Euch nicht im Stich lassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[38386] = { id = 38386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 008 - Shadowfen - twh" }
