quests[38393] = { id = 38393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 015 - Malorne's Refuge - twh" }
quests[38394] = { id = 38394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelwut", description = "Interessant – die Münzen, die Ihr aus Eurer Garnison mitgebracht habt, sehen ganz anders aus, als die, die Nolan in der Scherbenwelt gefunden hat. Seht Ihr die Markierungen am Rand? Diese Stücke sind sehr interessant! Ich würde gern weitere Untersuchungen anstellen, aber dafür brauch' ich mehr Münzen. Bringt mir noch ein paar mehr, es soll Euer Schaden nicht sein.", sourceObjective = "Bringt Krom Starkarm in Eisenschmiede fehlgeprägte draenische Münzen. Ihr könnt fehlgeprägte draenische Münzen beim Abschluss Eures ersten zufälligen heroischen Draenordungeons des Tages erhalten.", progress = "Und? Habt Ihr mir 'n paar Münzen mitgebracht?", completion = "Ich glaube, wir sind hier etwas ziemlich Großem auf der Spur.", sourceObjectiveStatus = "unverified-source-field" }
quests[38395] = { id = 38395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelwut", description = "Was soll das! Die Münzen, die du mir gebracht hast, passen nicht mit denen zusammen, die ich bereits habe! Du hast mir doch nicht etwa gefälschte Münzen untergejubelt, oder? Nein? Hmpf! Na gut, in dem Fall tut es mir leid, dass wir uns gestritten haben, mein Liebling.\n\nDann gibt es nur noch eine Möglichkeit, Herzchen: wir müssen alle Münzen der neuen Sammlung finden. Besorg mir mehr fehlgeprägte Münzen!", sourceObjective = "Bringt Estelle Gendry in Unterstadt fehlgeprägte draenische Münzen. Ihr könnt fehlgeprägte draenische Münzen beim Abschluss Eures ersten zufälligen heroischen Draenordungeons des Tages erhalten.", progress = "Ich hoffe, du hast genug Münzen mitgebracht, um diese Sammlung zu vervollständigen. Dann kann ich sie endlich verhö... äh, dann kann ich sie als Erinnerungsstücke aufbewahren.", completion = "So schwer war das doch gar nicht, oder, mein Schnuckelchen?\n\n<Estelle hält die Münzen, die Ihr gebracht habt, ins Licht und macht einen sehr zufriedenen Eindruck.>\n\nDiese Münzen sind wirklich sehr merkwürdig...", sourceObjectiveStatus = "unverified-source-field" }
quests[38396] = { id = 38396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine sensationelle Entdeckung", description = "Ich habe mir ein paar von den anderen Münzen angeschaut, die im Umlauf sind und diese dann mit denen verglichen, die Ihr mir gebracht habt. Einige davon sind einfach Fehlprägungen... andere sind völlig falsch. Schaut Euch diese hier an: zweimal Kopf. Auf der einen Seite grinst mich das Porträt an, obwohl es vorher keine Miene verzogen hat.\n\nIch glaube, wir sind hier auf etwas Gewaltiges gestoßen und diese Fehlprägungen sind der Schlüssel, um dieses Geheimnis zu lüften. Ich brauche noch mehr von diesen Münzen.", sourceObjective = "Bringt Krom Starkarm in Eisenschmiede fehlgeprägte draenische Münzen. Ihr könnt fehlgeprägte draenische Münzen beim Abschluss Eures ersten zufälligen heroischen Draenordungeons des Tages erhalten.", progress = "Wir stehen kurz vor dem Durchbruch.", completion = "Gut, gut! Ich habe nämlich einen verdächtig schrecklichen Verdacht bezüglich dieser merkwürdigen Münzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38397] = { id = 38397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine sensationelle Entdeckung", description = "Also mein Herzblatt, ich habe gute und schlechte Nachrichten für dich. Die gute Nachricht ist: Du hast mir genug Münzen gebracht, um diese neue Sammlung fehlgeprägter Münzen zu vervollständigen. Die schlechte Nachricht ist: Nicht eine dieser Münzen passt mit der ursprünglichen Sammlung zusammen. Schaut Euch diese Münze hier an: zweimal Kopf. Auf der Rückseite grinst mich das Porträt an, obwohl es vor einer Stunde noch ziemlich griesgrämig vor sich hin geschaut hat. Das hier kneift die Augen zusammen, wenn ich es ins Licht halte. Wirklich mysteriös! Ich brauche mehr von diesen Münzen!", sourceObjective = "Bringt Estelle Gendry in Unterstadt fehlgeprägte draenische Münzen. Ihr könnt fehlgeprägte draenische Münzen beim Abschluss Eures ersten zufälligen heroischen Draenordungeons des Tages erhalten.", progress = "Hat dir heute schon jemand gesagt, dass du einfach umwerfend aussiehst? Doch wirklich.", completion = "Mein Schnuckelchen, wenn das vorbei ist, werden wir beide als die Entdecker eines spektakulären paranormalen Phänomens in die Geschichte eingehen. Oder ich zumindest.", sourceObjectiveStatus = "unverified-source-field" }
quests[38398] = { id = 38398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Helyra's Kraken" }
quests[38399] = { id = 38399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefragte Rose", progress = "Möchtet Ihr etwas verkaufen?", completion = "Ah, ja, eine Eterniumrose. Ich hörte, dass die Verkäufer sie plötzlich nicht mehr annehmen wollen... Angeblich soll der Wiederverkaufswert zu gering sein.\n\nAber Ihr habt Glück, denn ich kenne einen Sammler, der noch welche von ihnen haben möchte. Also, ich könnte Euch die da gleich abnehmen. Aber dann müsstet Ihr morgen zurückkommen, wenn Ihr noch eine verkaufen möchtet." }
quests[38400] = { id = 38400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Grand Warlock Nethekurse" }
quests[38402] = { id = 38402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gleichen, aber nicht dieselben", description = "Ich habe langsam den Verdacht, dass diese Münzen dämonischen Ursprungs sind. Schaut her: Diese hier hat drei Augen! Und diese hier landet immer auf Zahl. Erinnert Ihr Euch an die Münzen, die Ihr mir vorher gebracht habt? Sie haben sich in Weihwasser einfach aufgelöst.\n\nIch muss ganz sicher geh'n, dass das kein Zufall ist. Bringt mir einen Riesenhaufen an Münzen für weitere Untersuchungen, damit niemand meine Theorie widerlegen kann.", sourceObjective = "Bringt Krom Starkarm in Eisenschmiede fehlgeprägte draenische Münzen. Ihr könnt fehlgeprägte draenische Münzen beim Abschluss Eures ersten zufälligen heroischen Draenordungeons des Tages erhalten.", progress = "Ausgezeichnete Arbeit! Die Forscherliga wird Euch als Helden feiern, so viel ist sicher.", completion = "Hört zu, ich habe mit den Priestern im Mystikerviertel geredet und sie haben meinen Verdacht bestätigt. Diese 'Fehlprägungen' sind allesamt dämonischer Herkunft.\n\nEs ist nur gut, dass Ihr sie aus dem Verkehr gezogen habt. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[38404] = { id = 38404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gleichen, aber nicht dieselben", description = "Ein Kollege von mir hat eine sehr interessante Theorie aufgestellt, die erklären könnte, was mit diesen Münzen nicht stimmt. Wir glauben, dass sie dämonischer Herkunft sind. Schau her: Diese hier hat drei Augen! Diese hier landet immer auf Zahl. Und DIESE hier raunt mir nachts zu – aber kein Grund, eifersüchtig zu werden, mein Herzblatt. Du bist immer noch mein Liebling.\n\n...Jedenfalls solange du mir mehr Münzen bringst, damit ich unsere Theorie untermauern kann. Also los, mach dich auf den Weg!", sourceObjective = "Bringt Estelle Gendry in Unterstadt fehlgeprägte draenische Münzen. Ihr könnt fehlgeprägte draenische Münzen beim Abschluss Eures ersten zufälligen heroischen Draenordungeons des Tages erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[38405] = { id = 38405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wetterfeste Ausrüstung", description = "Ich habe mich ein bisschen umgehört und anscheinend machen diese Vrykul selbst gern regelmäßige Ausflüge in die Berge. Dafür verwenden sie spezielle Ausrüstung, die wir auch gut brauchen könnten.\n\nVielleicht könnt Ihr ihnen ja ein paar Kletterschuhe für einen besseren Halt auf den Abhängen abnehmen. Ein gefetteter Umhang wäre auch ganz nützlich gegen den Regen. Außerdem scheinen sie verzauberte Leitsteine mit sich zu führen, mit denen man sich vor Blitzen schützen kann. So einer wäre auch ganz praktisch.", sourceObjective = "Sammelt Kletterschuhe, einen gefetteten Umhang und einen verzauberten Leitstein in Hrydshal.", progress = "Habt Ihr alles gefunden?", completion = "Ausgezeichnet. Damit solltet Ihr gut gegen die Stürme geschützt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[38406] = { id = 38406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeskorpionoschi", progress = "Ein gigantischer Seeskorpion?", completion = "Dieses gewaltige Exemplar muss jahrelang gewachsen sein. Der Kleine ist so niedlich, dass ich ihn wahrscheinlich gleich wieder zurück ins Wasser werfe. Vielleicht habt Ihr ihn eines Tages nochmal an der Angel." }
quests[38407] = { id = 38407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flaschenpost", description = "<Ihr habt bei der Leiche eine Flaschenpost gefunden. Es ist ein Hilferuf von jemandem namens Okuna Langhauer. Okuna berichtet, dass er zusammen mit seinen Schiffskameraden von Seeriesen gefangen gehalten wird.\n\nVielleicht kann Euch ja Lady Irisse am Zerfallenen Palast zeigen, wo das ist, wenn Ihr ihr diesen Brief zeigt?>", sourceObjective = "Bringt Okunas Nachricht zu Lady Irisse.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt diese Nachricht in einer Flasche gefunden? Wie kurios.\n\nJa, ich kann Euch zeigen, wo das ist. Aber seid Ihr sicher, dass Ihr Euch mit dem Riesenprinzen und seinen Skrogs anlegen wollt? Nur um einen Haufen ungewaschener Matrosen zu befreien?", sourceObjectiveStatus = "unverified-source-field" }
quests[38408] = { id = 38408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brandneue Ware", description = "Unteroffizier Krähler hat neue Gegenstände im Angebot. Vielleicht solltet Ihr mal bei ihm vorbeischauen und Euch seine neuen Waren anschauen!", sourceObjective = "Sprecht mit Unteroffizier Krähler.", sourceObjectiveStatus = "unverified-source-field" }
quests[38410] = { id = 38410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speerabwehr", description = "Ich habe schlechte Neuigkeiten. Diese Harpunenschleudern auf den Mauern könnten uns Probleme bereiten.\n\nHier unten sind wir außer Reichweite, aber sobald wir uns den Pfad hinaufwagen, machen sie Schaschlik aus uns.\n\nMit diesem Greifhakenwerfer solltet Ihr es auf die Mauern schaffen, dort könnt Ihr sie dann auseinandernehmen. Doch achtet dabei auf die Drachen!", sourceObjective = "Nutzt einen Greifhaken, um auf die Mauern von Hrydshal zu gelangen, und zerlegt 7 Harpunenschleudern der Wellenskorn.", completion = "Hah! Damit hatten sie sicher nicht gerechnet!\n\nAber es warten wohl noch viele weitere Hindernisse auf uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[38411] = { id = 38411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Executor Riloth" }
quests[38412] = { id = 38412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über dem Wintermondlicht", description = "Von diesem Turm aus solltet Ihr Euch leicht zum Gebirgspfad rüberhangeln können. Wenn Ihr da drüben seid, kann ich Euch nicht mehr helfen, aber der Pfad sollte Euch bis zum Gipfel führen. \n\nIch hoffe, dass Ihr bei den Drachen da oben findet, wonach Ihr sucht. Wer weiß, was der Gottkönig denen angetan hat.", sourceObjective = "Hangelt Euch vom Turm hinüber und steigt dann zum Gipfel des Gebirgspfads hoch.", completion = "Ihr seid wegen der Prüfung hier? Ich fürchte, dass Ihr zu spät seid.\n\nDieser Kampf mit den Teufelsskorn hat seine Spuren hinterlassen. Ich bin zu schwach, um Euch die gewünschte Kraft zu verleihen...\n\nAber vielleicht könnt Ihr mir helfen...", sourceObjectiveStatus = "unverified-source-field" }
quests[38413] = { id = 38413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwingen der Freiheit", description = "Als die Teufelsskorn das Nest angriffen, haben die Thorignir tapfer gekämpft, um unsere Brut zu schützen. Aber ihre dämonischen Verbündeten waren zu stark, und so sind viele von uns gefangen genommen worden.\n\nWährend wir hier sprechen, versuchen sie, meine Brüder und Schwestern zu verderben und auf ihre Seite zu ziehen.\n\nIch bitte Euch, <Fremder/Fremde>, bewahrt sie vor diesem Schicksal!", sourceObjective = "Befreit Aleifir, Hrafsir, Erilar und Hridmogir am Thorimshorn.", progress = "Welche Neuigkeiten könnt Ihr über meine Brüder und Schwestern berichten?", completion = "Dafür stehe ich tief in Eurer Schuld. Meine Nachkommen konnten sich nicht gegen die Teufelsskorn behaupten und hätten als Sklaven geendet.\n\nIhr seid ein wahrer Freund der Thorignir.", sourceObjectiveStatus = "unverified-source-field" }
quests[38414] = { id = 38414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz eines Drachen", description = "Mithilfe brutaler Gewalt und Verderbnis hat der Gottkönig die Macht an sich gerissen, die Ihr sucht. Aber vielleicht gibt es noch Hoffnung für Euch und die Thorignir, {class}.\n\nDie Teufelsskorn nutzen teuflische Mächte, wie ich sie noch nie gesehen habe, um unsere Nachkommen zu verderben und die Thorignir zu versklaven. Ihr Anführer, ein mächtiger Dämon, hat unsere Mutter entführt und will sie dem Willen des Gottkönigs unterwerfen.\n\nFindet sie und befreit sie aus den Fängen des Dämons. Nur dann können die Thorignir ihre Macht zurückerlangen und Euch helfen.", sourceObjective = "Sucht nach der Mutter der Thorignirbrut und rettet sie.", completion = "Ich bin erleichtert zu hören, dass unsere Mutter in Sicherheit ist.\n\nIch bin mir sicher, dass sie Euch noch persönlich danken möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[38415] = { id = 38415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Ansturm auf Auchindoun", description = "Eure Verbündete, Liadrin, erbittet in einem Schreiben Hilfe in der Nähe von Auchindoun. Die Sargerei haben dort einen neuen Angriff gestartet und ein wichtiges Ziel getroffen. Es ist bestimmt kein Zufall, dass dies nach dem Aufstieg von Gul'dan passiert ist. Wir werden unsere Front hier im Auge behalten, Kommandant.", sourceObjective = "Trefft Euch mit Liadrin bei Auchindoun in Talador.", completion = "Ich weiß, dass der Kampf in Tanaan Euren Streitkräften sehr zusetzt, Kommandant. Ich bin froh, dass Ihr hergekommen seid. Die Sargerei und Gul'dan dienen denselben Meistern, also hat dieser erneute Angriff sicher auch Auswirkungen auf Eure Situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[38416] = { id = 38416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Sargerei", description = "Die Auchenai berichten schon seit einiger Zeit, dass etwas mit Auchindoun nicht stimmt. Sie konnten nie einen Grund dafür finden. Dann haben plötzlich die Sargerei angegriffen und ein Loch in eine der unteren Kammern gesprengt.\n\nAus diesem Loch strömt nun Verderbnis, und wir müssen sie aufhalten.", sourceObjective = "Sucht nach der Quelle der Verderbnis unter Auchindoun und bringt sie zum Versiegen.", completion = "Das ist bedauerlich. Wir können Blutschatten nicht gestatten, bei Gul'dans Machenschaften mitzuwirken. Er muss ein für alle Mal erledigt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[38417] = { id = 38417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sargereibedrohung", description = "Ein derartiger Angriff kam völlig unerwartet. Ihre Zahl ist groß, und ich werde einige Zeit brauchen, um ausreichende Streitkräfte aufzustellen und sie auszumerzen.\n\nMit jedem Sargerei, den Ihr töten könnt, wird die Rückeroberung dieses Gebiets wesentlich einfacher, Kommandant.", sourceObjective = "Tötet 12 Sargerei.", sourceObjectiveStatus = "unverified-source-field" }
quests[38419] = { id = 38419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 018 - [The Greenway]" }
quests[38421] = { id = 38421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Ansturm auf Auchindoun", description = "Die Auchenai haben mir ein dringendes Schreiben geschickt: Auchindoun ist wieder in Gefahr! Die Sargerei haben erneut angegriffen und sind in die Kellergewölbe eingedrungen. Ich spüre, dass die Hand Gul'dans dahintersteckt.\n\nPackt Eure Sachen und trefft Euch schnellstens mit mir im Hof der Seelen westlich von Auchindoun!", sourceObjective = "Trefft Euch mit Yrel bei Auchindoun in Talador.", completion = "Ich bin froh, dass Ihr sofort gekommen seid. Etwas Furchtbares braut sich unter diesem heiligen Ort zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38422] = { id = 38422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makrura Wave Event" }
quests[38423] = { id = 38423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Stormdrake Matriarch" }
quests[38424] = { id = 38424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thane's Mead Hall" }
quests[38425] = { id = 38425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Fel Thorignir" }
quests[38426] = { id = 38426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Tome of Secrets" }
quests[38427] = { id = 38427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brandneue Ware", description = "Unteroffizier Grimmkinn hat neue Gegenstände im Angebot. Vielleicht solltet Ihr mal bei ihm vorbeischauen und Euch seine neuen Waren anschauen!", sourceObjective = "Sprecht mit Unteroffizier Grimmkinn.", sourceObjectiveStatus = "unverified-source-field" }
quests[38428] = { id = 38428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein eigener Teufelswelpe", sourceObjective = "<Der Welpe leckt zögerlich an Eurer Hand. Nachdem Ihr ihn gründlich hinter den Ohren gekrault habt, bellt der Welpe und wedelt mit dem Schwanz.>", sourceObjectiveStatus = "unverified-source-field" }
quests[38430] = { id = 38430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Argosh the Destroyer" }
quests[38431] = { id = 38431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Bladesquall" }
quests[38433] = { id = 38433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan Jungle - Tracking Quest - Lion's Watch Built - JMC" }
quests[38435] = { id = 38435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Invasion von Tanaan", description = "Es ist vollbracht! Auf Euren Befehl haben wir unser erstes Schiff fertiggestellt und können unsere Operationen von hier aus starten.\n\nNun da wir einen Truppentransporter haben, können wir Yrel und Erzmagier Khadgar wissen lassen, dass die Invasion von Tanaan beginnen kann. Sprecht an den Docks mit ihnen, um abzulegen.", sourceObjective = "Trefft Euch mit Khadgar bei Eurer Schiffswerft und sprecht dann mit Yrel, um die Invasion zu starten.", completion = "Die Landung war einfacher, als ich erwartet hatte, aber vor uns liegt Ärger.", sourceObjectiveStatus = "unverified-source-field" }
quests[38436] = { id = 38436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hindernislauf", description = "Wir konnten ungehindert landen. Warum sind diese Docks komplett verlassen?\n\nDie Rangarispäher voraus melden jedoch Schwierigkeiten. Plünderer des Blutenden Auges suchen verlassene Gebäude nordwestlich von hier heim, und Hexenmeister der Kultisten haben in der Nähe des Dunklen Portals ein Lager aufgeschlagen. Treffen wir uns mit den Spähern und finden wir so viel heraus wie möglich.", sourceObjective = "Sucht nach Informationen zu den in dem Gebiet befindlichen Streitkräften und trefft Euch anschließend mit den Spähern.", completion = "Unsere Streitkräfte können sich um die restlichen Feinde kümmern. Aber vor uns gibt es weitere Probleme.", sourceObjectiveStatus = "unverified-source-field" }
quests[38437] = { id = 38437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - The Fel Forge" }
quests[38438] = { id = 38438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - The Fel Forge" }
quests[38439] = { id = 38439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Dämonenschmiede", description = "Die Eiserne Horde schafft ununterbrochen neue Verstärkungen aus ganz Draenor heran, um ihre Position bei der Höllenfeuerzitadelle zu festigen. Wenn es uns nicht gelingt, ihnen den Nachschub abzuschneiden, geraten unsere Pläne in Tanaan in Gefahr.\n\nJetzt ist ein strategischer Angriff auf die Nachschublinien im Eisenfausthafen die erste Wahl, um die Eiserne Horde weiter in die Defensive zu drängen und selbst die Kontrolle zu wahren.", sourceObjective = "Greift die Nachschubeinheiten der Eisernen Horde im Eisenfausthafen im Tanaandschungel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[38440] = { id = 38440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Dämonenschmiede", description = "Weil ihre Kriegsmaschinen mit Teufelsmagie verstärkt sind, wird die Eiserne Horde mit jedem Tag stärker. Wir haben gehört, dass sie sogar einen Teufelshäscher bauen sollen!\n\nBegebt Euch zur Dämonenschmiede und vernichtet ihre Truppen, bevor sie uns überrennen.", sourceObjective = "Greift die Truppen der Eisernen Horde bei der Dämonenschmiede im Tanaandschungel an.", completion = "Willkommen zurück, Kommandant. Unsere Späher haben uns bereits von Euren Erfolgen berichtet.\n\nGut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[38441] = { id = 38441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Dämonenschmiede", description = "Weil ihre Kriegsmaschinen mit Teufelsmagie verstärkt sind, wird die Eiserne Horde mit jedem Tag stärker. Wir haben gehört, dass sie sogar einen Teufelshäscher bauen sollen!\n\nBegebt Euch zur Dämonenschmiede und vernichtet ihre Truppen, bevor sie uns überrennen.", sourceObjective = "Greift die Truppen der Eisernen Horde bei der Dämonenschmiede im Tanaandschungel an.", progress = "Wie verläuft der Angriff, General?", completion = "Die Späher haben schon von Euren Erfolgen berichtet.\n\nLok'tar!", sourceObjectiveStatus = "unverified-source-field" }
quests[38442] = { id = 38442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein würdiger Herausforderer" }
quests[38443] = { id = 38443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zur Rast", description = "Zurzeit können die Illidari noch die Front gegen die Legion halten. Wir werden später zurückkehren und ihnen helfen, die Legion aus den höheren Gebieten Faronaars zu vertreiben. Aber jetzt müssen wir uns auf die Säulen der Schöpfung konzentrieren, um das Grabmal des Sargeras zu versiegeln.\n\nEs ist ein glücklicher Umstand, dass Ihr Stellagosa gerettet habt. Wenn jemand den Standort einer Säule der Schöpfung kennt, dann ist es ihr Großvater Senegos.\n\nDie Azurschwingenrast befindet sich im Nordosten. Ich treffe Euch dann dort, {name}.", sourceObjective = "Sprecht mit Erzmagier Khadgar bei der Azurschwingenrast.", completion = "Er... Er stirbt! Senegos ist vermutlich der älteste noch lebende Drache. Wir dürfen nicht zulassen, dass er uns einfach so entgleitet.\n\nIrgendetwas stimmt mit der magischen Energie hier nicht. Ich kann es spüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[38444] = { id = 38444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rein, durch und weiter!", description = "Gul'dan scheint seine Verteidigungskräfte an diesem Engpass konzentriert zu haben. Solche Schusswaffen haben wir noch nie zuvor gesehen... Sie funktionieren mit Teufelsenergie.\n\nUnsere Feinde glauben, dieser Pass wäre unüberwindlich. Beweisen wir ihnen das Gegenteil, Kommandant! Wenn wir durchbrechen können, eignet sich das Gebiet dahinter ausgezeichnet für eine Festung. Zerstört diese Kanone!", sourceObjective = "Zerstört die teuflische Verteidigungskanone, die dem Tor Deckung gibt.", completion = "Keine Sorge, in Kürze kommt ein Einsatzkommando, das hier den Rest aufräumt. Wir sollten uns in Bewegung setzen, bevor die feindlichen Boten Gul'dan erreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38445] = { id = 38445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Angriffsbasis", description = "Während Ihr mit dem Teufelsfeuer gespielt habt, habe ich die perfekte Position für einen Angriffsaußenposten ausgemacht.\n\nFolgt mir, dann können wir den Grundstein zu dieser Basis legen!", sourceObjective = "Errichtet Eure Angriffsbasis im Tanaandschungel.", completion = "Das war der leichte Teil, jetzt wird's schwieriger.", sourceObjectiveStatus = "unverified-source-field" }
quests[38446] = { id = 38446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant im Feld!", description = "Wir werden diese Schlacht gewinnen, doch wird der Sieg hart erkämpft werden müssen. Unsere Rangari haben es jedoch geschafft, ein paar Späher in den Rest des Dschungels zu entsenden.\n\nVielleicht wäre es am besten, wenn Ihr die Informationen persönlich besorgt und herausfindet, was dieser Dschungel für uns bereithält.", sourceObjective = "Sammelt Berichte von den verschiedenen Spähern im Tanaandschungel.", completion = "Das wird ganz sicher ein schwieriger Feldzug.", sourceObjectiveStatus = "unverified-source-field" }
quests[38449] = { id = 38449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Tempel von Sha'naar", description = "Oben in den Hügeln des Tanaandschungels haben die Sargerei einen einstmals heiligen Tempel in einen Hort dämonischer Rituale verwandelt.\n\nWir müssen sie sofort angreifen, bevor sie ihre Rituale vollendet haben. Je länger wir warten, desto stärker werden unsere Feinde.", sourceObjective = "Greift die Sargereitruppen im Tempel von Sha'naar im Tanaandschungel an.", completion = "Willkommen zurück, General. Unsere Späher haben uns bereits von Euren Erfolgen berichtet.\n\nGut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[38451] = { id = 38451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Geir Gutslice" }
quests[38452] = { id = 38452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Hidden Demon" }
quests[38453] = { id = 38453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Schrecken des Blutenden Auges", description = "Kommandant, wo wir nun die Zeit hatten, Späher in den ganzen Dschungel zu entsenden, haben wir Neuigkeiten aus der Nähe von Zeth'Gol.\n\nAnscheinend pflegt noch jemand eine Blutrache gegen das Blutende Auge und... ähm... macht Jagd auf sie. Die Jäger des Blutenden Auges kommen diesem Meuchler immer näher.\nIhr kennt ja das Sprichwort: \"Der Feind meines Feindes...\" Wir sollten uns ihre Fährtenleserkarten besorgen und versuchen, diesen Jäger vor ihnen zu finden.", sourceObjective = "Sammelt die Fährtenleserkarten, um den Aufenthaltsort des Jägers zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[38455] = { id = 38455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasende Furbolgs", description = "Ich würde Euch zum Treffen mit dem Erzdruiden begleiten, aber wir haben hier selbst einige Probleme.\n\nDie Furbolgs in dieser Gegend sind in Raserei verfallen.\n\nSeit Tagen schon müssen wir unseren Hain gegen ihre Angriffe verteidigen.\n\nSie haben uns den Weg zur Höhle der Schläfer abgeschnitten. Das ist der Ort, wo der Erzdruide und unser Klan im Smaragdgrünen Traum schlafen.\n\nUm sie erwecken zu können, müssen wir zuerst an den Furbolgs vorbei.", sourceObjective = "Tötet 8 Schwelhautfurbolgs.", completion = "Die Furbolgsituation ist unter Kontrolle... vorerst zumindest.", sourceObjectiveStatus = "unverified-source-field" }
quests[38457] = { id = 38457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Putre'thar" }
quests[38458] = { id = 38458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Hexenmeister", description = "Kommandant, Ihr habt Besuch. Einer von Gul'dans Hexenmeistern hat sich unserer Basis genähert und sich ergeben. Er sagt, er hat Informationen über ein schreckliches Ereignis, das bald eintreten soll.\n\nIch schlage vor, dass Ihr sofort mit ihm sprecht.", sourceObjective = "Sprecht mit dem Hexenmeister bei Vol'mar im Tanaandschungel.", completion = "Ich kam zu spät, um Euch die Nachricht rechtzeitig zu überbringen. Es tut mir wirklich leid. Diese armen Schamanen... Wenn ich es nur früher gewusst hätte!\n\nGul'dan hat alles für sein Ritual vorbereitet. Er wird die Litanei und seine eigene Teufelsmagie einsetzen, um einen Elementarlord zu verderben. Er will ihn dann dazu bringen, die Elementarverbindung zum Land zu trennen. Das wird einen gewaltigen Aufruhr in ganz Draenor nach sich ziehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[38459] = { id = 38459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die uralten Prüfungen", description = "<Während Euch der Rabe in die Augen starrt, dringt eine seltsame Stimme in Euren Geist.>\n\nIch weiß, wer Ihr seid, Champion, und ich weiß, wonach Ihr sucht.\n\nKommt zu mir, wenn Ihr Euch selbst als würdig erachtet.", sourceObjective = "Sucht nach Havi in der Nähe von Aggramars Kammer.", completion = "Ich weiß, dass Ihr viele Fragen habt. Die Antworten erhaltet Ihr beizeiten.\n\nIch bin Havi und ich spreche für die Valarjar, die ruhmreichen Hüter der Hallen der Tapferkeit.\n\nIhr werdet meine Hilfe benötigen, wenn Ihr nach der Aegis sucht. Ja, ich weiß um Eure Pläne, Fremder. Denn ich weiß um viele Dinge...", sourceObjectiveStatus = "unverified-source-field" }
quests[38460] = { id = 38460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommen wir ins Geschäft!", description = "Hey, Ihr da!\n\nIhr scheint mir ja recht leichtgläu... äh... \"intelligent\" zu sein.\n\nIch will Euch ein Geschäft vorschlagen.\n\nIch brauche einen kräftigen Helfer, um ein paar... \"Zutaten\" für ein Ritual zu sammeln.\n\nIm Gegenzug biete ich meinen früheren Meister an. Ihr könnt dann mit ihm machen, was immer Ihr Dämonenschlächtertypen mit Dämonen so macht.\n\nWenn Ihr einverstanden seid, dann unterschreibt bitte hier... mit Eurem Blut.", sourceObjective = "Unterschreibt Daglops Vertrag.", completion = "Endlich! Endlich mein höchstpersönlicher Diener!", sourceObjectiveStatus = "unverified-source-field" }
quests[38461] = { id = 38461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Guarms Mate (Fenri)" }
quests[38462] = { id = 38462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brechen der Barriere", description = "Die Ritualstätte ist bereits vorbereitet und ist durch eine Barriere geschützt... durch eine Barriere, die ich geschaffen habe. Ich kann diese Barriere zerstören, doch brauche ich dazu drei Gegenstände, die derzeit im Konstruktionslager: Rache verwendet werden.\n\nWenn Ihr diese rituellen Gegenstände besorgen könnt, werde ich mich mit Euch im Verderbten Refugium treffen und die Barriere entfernen... auch, wenn es mich umbringt.", sourceObjective = "Besorgt die schwarze Kerze, den Folianten des Schutzes und die Schattenklinge in der Dämonenschmiede und bringt die Sachen zu Oronok.", completion = "Nicht einen Augenblick zu früh. Er hat irgendetwas beschworen. Ich befürchte, das Ritual ist schon fast abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38463] = { id = 38463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Litanei der Verdammnis", description = "Euer Verbündeter und ich werden diese Barriere jetzt entfernen, auch wenn es einen Großteil unserer Stärke aufbrauchen wird. Was jenseits der Barriere folgt, wird nicht einfach werden.\n\nGul'dan wird mithilfe der Litanei einen Elementarlord ermächtigt und in den Wahnsinn getrieben haben. Er wird ihn einsetzen, um die Verbindung zwischen den Elementen und Draenor zu zerstören. Wenn Ihr diesen Elementar vernichtet, können wir die Litanei bergen.", sourceObjective = "Lasst Oronok und Euren Verbündeten die Barriere zerstören und haltet dann Gul'dan auf.", completion = "Ihr habt uns alle gerettet. Die Litanei ist bei dem Tod von Cyrukh in mehrere Fragmente zerfallen. Das bedeutet, dass die Wächter die Splitter in ganz Draenor verbergen können und man sie unmöglich wieder zusammensetzen kann.\n\nDieser Sieg wird in die Hallen Eurer Krieger getragen und sie zu noch größeren Taten ermutigen. Gul'dan kann ruhig weiter Pläne schmieden... er wird dennoch scheitern...", sourceObjectiveStatus = "unverified-source-field" }
quests[38465] = { id = 38465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shyama the Dreaded" }
