quests[38472] = { id = 38472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitewater Typhoon" }
quests[38473] = { id = 38473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille der Thorignir", description = "Wo die Stürme am heftigsten tosen, erwarten Euch die Drachen. Sie sind Nachkommen der Götter und werden Eure Willensstärke auf die Probe stellen.\n\nSie leben oberhalb von Hrydshal, wo ihre Kinder den Drekirjar dienen. Allerdings sind sie keine Verbündeten der Menschen oder der Vrykul. Daher müsst Ihr versuchen, ihre Gunst zu gewinnen.\n\nEine Freundin erwartet Euch in Hrydshal und ist zweifelsohne auf der Suche nach Antworten, die Ihr nun habt. Geht zu ihr und stellt Euch gemeinsam der Macht des Sturms!", sourceObjective = "Trefft Euch außerhalb von Hrydshal mit Lorna Crowley, um mit der Prüfung der Thorignir zu beginnen.", completion = "Es ist schön, Euch zu sehen, {name}. Graumähne hat mich ausgesandt, in diesem Dorf nach weiteren Informationen über die Aegis zu suchen.\n\nBisher habe ich nur herausgefunden, dass die Einheimischen eher unfreundlich sind. Aber wann sind sie schon jemals wirklich freundlich...\n\nIch hoffe, Eure Suche läuft besser.", sourceObjectiveStatus = "unverified-source-field" }
