quests[38498] = { id = 38498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 018 - Maw of Nashal - ZTO" }
quests[38499] = { id = 38499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsame neue Erze", description = "Könnt Ihr das auch riechen, <Schmied/Schmiedin>? Ahhhh... Das ist der Geruch einer Gelegenheit.\n\nDalaran hat uns an ganz neue Gestade voller mysteriöser Metalle gebracht. Ich kann hier nicht aus meinem Laden raus, aber Ihr... Ihr habt die Freiheit, so viel zu erkunden und abzubauen, wie Ihr wollt.\n\nWenn Ihr mir etwas Interessantes mitbringt, werde ich sehen, was wir daraus machen können.", sourceObjective = "Sammelt 10 Brocken Leysteinerz.", progress = "Habt Ihr etwas Interessantes gefunden?", completion = "Faszinierend...", sourceObjectiveStatus = "unverified-source-field" }
quests[38500] = { id = 38500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyschmiedemeisterschaft", description = "Jetzt, wo uns der Flux zur Verfügung steht, können wir ihn ja mal ausprobieren. Versucht doch, ein paar Stulpen für mich herzustellen. Ich werde Euch bei der Arbeit beobachten... aus der Ferne.", sourceObjective = "Folgt Alard Schmieds Plänen in Eurer Liste der Schmiedekunstpläne und stellt ein paar handgefertigte Leysteinstulpen her.", progress = "Hat es funktioniert? Ich habe noch keine Explosion gehört.", completion = "Ausgezeichnete Arbeit! Dieser neue Flux könnte auch enormen Einfluss auf andere verarbeitbare Materialien haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[38501] = { id = 38501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt von den Hassnattern", description = "Es gibt vielleicht einen Weg, unsere Leysteinforschungen schneller voranzutreiben.\n\nIch habe von den Nagalagern in Azsuna gehört. Wenn sie schon lange genug in Azsuna sind, haben ihre Schmiede sicherlich auch schon angefangen, selbst mit Leystein zu experimentieren.\n\nVersucht, ein paar Leysteinrüstungsteile der Naga zu ergattern... im besten Fall etwas Aufwendigeres als Armschienen.", sourceObjective = "Besorgt eine meisterliche Brustplatte der Hassnattern und ein Paar meisterliche Schulterstücke der Hassnattern.", progress = "Ich finde es immer noch faszinierend, wie schnell diese Biester in diesen Plattenrüstungen schwimmen können.", completion = "Natürlich! Sie sind das Problem mit den Schweißarbeiten umgangen, indem sie die Rüstungsteile einfach aus einem einzigen Stück Metall gefertigt haben.\n\nDie Schulterstücke hätte ich auch hinbekommen, aber diese Brustplatte ist wirklich bemerkenswert.\n\nHier, ich werde Euch ein paar Muster aufzeichnen, damit Ihr sie selbst herstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38502] = { id = 38502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Methoden der Nachtsüchtigen", description = "Ich habe eine Theorie, {name}.\n\nSeid Ihr jemals den nachtsüchtigen Elfen von Azsuna begegnet? Sie sind Nachkommen der Hochgeborenen, und die Werke der Hochgeborenenschmiede sind legendär.\n\nDiese gefallenen Elfen experimentieren mit arkaner Magie und erstellen Wächterkonstrukte, die sie durch ihre Lager patrouillieren lassen.\n\nBringt mir einen der Speicherkerne dieser Konstrukte. Wer weiß, was er uns über ihre Schmiedekunst verraten kann!", sourceObjective = "Beschafft den Speicherkern eines uralten Wächterkonstrukts.", progress = "Hoffentlich können wir etwas Nützliches aus ihnen herausholen.", completion = "Wenn meine Theorie stimmt, dann finden wir in diesem Kern die Antwort auf unsere Probleme mit den Schweißarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[38503] = { id = 38503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 020 - Helheim - ZTO" }
quests[38504] = { id = 38504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of the Bear Twins" }
quests[38505] = { id = 38505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingenieure: Nicht TOTAL nutzlos", description = "Leider habe ich selbst keine Ahnung, wie man an die Informationen in diesem Kern herankommt. Aber ich kenne da jemanden.\n\nBesucht den Ingenieursladen \"Auf die Sekunde\" drei Türen weiter die Straße runter. Timofey Oshenko schuldet mir noch einen Gefallen. Er sollte die Informationen aus diesem Kern auslesen können.", sourceObjective = "Bringt den Speicherkern eines uralten Wächterkonstrukts zu Timofey Oshenko in Dalaran.", progress = "Alard schickt Euch? Was will der Muskelprotz jetzt wieder von mir?", completion = "Oh, ein Speicherkern? Einen Moment...", sourceObjectiveStatus = "unverified-source-field" }
quests[38506] = { id = 38506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hühnergekritzel", description = "Ich glaube, ich habe genau das Richtige, um die Informationen aus diesem Kern zu holen.\n\n<Timofey gibt den Kern in den Trichter einer offensichtlich von Goblins erschaffenen Maschine und hält sich dann die Ohren zu.>\n\nIhr solltet vielleicht Eure Augen abwenden.", sourceObjective = "Bringt den uralten Datendruck der Hochgeborenen zu Professor Pallin in Dalaran.", progress = "Die Hochgeborenen! Uralte Hochgeborene! Was für ein erstaunlicher Fund!", completion = "...würde ich sagen, wenn wir nicht direkt über der Heimat der Ahnen der Hochgeborenen wären. Braucht Ihr eine Übersetzung oder sowas?", sourceObjectiveStatus = "unverified-source-field" }
quests[38507] = { id = 38507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse des Leyschmiedens", description = "Ich könnte Stunden mit dem Studium der faszinierenden Details dieses Manuskripts verbringen!\n\n... Oder zumindest würde ich das behaupten, wenn ich nicht ohnehin schon alles darüber wüsste. Es geht dabei ums \"Leyschmieden\". Hier.\n\n<Der Gnom kritzelt eine Übersetzung auf die Rückseite der Schriftrolle.>\n\nDa habt Ihr es, Wort für Wort. Bringt mir nächstes Mal etwas Interessantes mit.", sourceObjective = "Bringt den Leitfaden der Leyschmiedekunst zu Alard Schmied in Dalaran.", progress = "Habt Ihr den Ingenieursladen gefunden?", completion = "Ich hatte gar nicht daran gedacht, dass Ihr ja auch eine Übersetzung brauchen würdet. Gut mitgedacht.\n\nTja, aus genau diesem Grund beschäftige ich immer wieder Abenteurer wie Euch in diesem Laden.", sourceObjectiveStatus = "unverified-source-field" }
quests[38508] = { id = 38508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of the Bear Twins - Reward" }
