quests[38510] = { id = 38510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 021 - Helheim - ZTO" }
quests[38511] = { id = 38511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 022 - Helheim - ZTO" }
quests[38512] = { id = 38512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oakleaf" }
quests[38513] = { id = 38513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schmiede des Hochbergs", description = "Ich glaube, wir sind jetzt an die Grenzen meines Wissens gestoßen, {name}.\n\nUnter den Tauren vom Hochberg wird es sicherlich einige Schmiede geben. Seht, ob Ihr Eure Leyschmiedekunst bei ihnen weiter verbessern könnt.", sourceObjective = "Sprecht mit Barm Steinbrecher auf dem Hochberg.", completion = "Ihr haltet Euch für würdig, an unserer Weisheit teilzuhaben, Fremdling?", sourceObjectiveStatus = "unverified-source-field" }
quests[38514] = { id = 38514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid nicht würdig", description = "Ihr möchtet, dass ich Euch beibringe, wie Ihr Eure Handwerkskünste verbessern könnt? Wir teilen unser Wissen nicht einfach mit Fremden, die darum bitten.\n\nAllerdings respektieren wir alle, die handwerkliche Fähigkeiten und Disziplin unter Beweis stellen.\n\nLasst mal sehen, wie Ihr mit dem Hammer umgehen könnt. Unsere Anfänger verwenden die kleinen Ambosse dort drüben. Stellt Euer bestes Paar Stulpen her, damit ich Eure Schmiedefertigkeiten beurteilen kann.", sourceObjective = "Macht Gebrauch von Euren Schmiedefertigkeiten und stellt ein Paar Leysteinstulpen für Barm her.", progress = "Ich warte, Fremder.", completion = "Eure Fertigkeiten sind nicht schlecht, aber die Qualität ist verbesserungsbedürftig.\n\n<Barm bricht die Stulpen in der Mitte durch und wirft sie zu Boden.>\n\nIhr habt Euch nicht als würdig erwiesen, von mir lernen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38515] = { id = 38515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gaben der Natur", description = "Das ist interessant... Angeblich soll Leystein mit allem, was er als Verunreinigung auffasst, heftig reagieren. Unser in der Fremde gewonnener Flux hat ausgereicht, um die kleine Explosion auszulösen.\n\nDie hiesigen Substanzen haben aber gelernt, neben dem Leystein zu existieren. Oben auf dem Hochberg gibt es ein Kraut namens \"Fuchsblume\". Aus ihm kann man einen geeigneten Flux gewinnen.\n\nSammelt ein paar Fuchsblumen ein, damit wir einen Vorrat an Flux anlegen können.", sourceObjective = "Sammelt 10 Fuchsblumen.\n\nWenn Ihr der Kräuterkunde nicht mächtig seid, könnt Ihr die Fuchsblumen im Auktionshaus kaufen oder von anderen Spielern erhalten.", progress = "Wie läuft die Suche nach den Fuchsblumen?", completion = "Ausgezeichnete Arbeit. Und jetzt wollen wir sie gleich in Flux umwandeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[38516] = { id = 38516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 022 - Helheim - ZTO" }
quests[38517] = { id = 38517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tayla's Rescue" }
quests[38518] = { id = 38518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Meister zu Meister", description = "Kehrt nun zu Eurem Meister in Dalaran zurück und arbeitet an Eurem Schwung mit dem Hammer. Wenn Ihr mehr lernen möchtet, könnt Ihr jederzeit zu uns zurückkehren.", sourceObjective = "Kehrt zu Alard in Dalaran zurück und teilt ihm mit, was Ihr von den Tauren gelernt habt.", completion = "Verstehe... Die Qualität ihrer Arbeit basiert auf den Techniken ihrer Hammerschläge. Das ist sehr interessant...", sourceObjectiveStatus = "unverified-source-field" }
quests[38519] = { id = 38519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grauwucht", description = "Unser Stamm stellt regelmäßig Beinplatten aus Leystein her. Ich werde mein Muster mit Euch teilen, wenn Ihr mir einen Gefallen erweist...\n\nMein Vater wurde vor vielen Jahren von den Drogbar getötet und sie haben seinen Hammer als Trophäe an sich genommen. Dieser Hammer befand sich seit unzähligen Generationen im Besitz meiner Familie. Und jetzt hält ihn dieser widerwärtige Drogbar, Kubrul, in seinen schmutzigen Händen.\n\nIch hätte ihn wirklich sehr gern zurück.", sourceObjective = "Beschafft Grauwucht, den uralten Hammer der Hochbergtauren, von Kubrul innerhalb der Tiefenpfade.", progress = "Ich habe keine Muster für Helme oder Stiefel.\n\nEin Tauren, der ein paar Schläge auf die Hufe nicht einstecken kann, hat nichts im Kampf zu suchen. Mit Stiefeln können wir nichts anfangen.\n\nUnd Helme sind nur für Feiglinge. Tut mir leid, wenn ich Euch damit beleidige, aber so ist es nun einmal.\n\nBeinplatten sind allerdings sehr wichtig. Deshalb werde ich Euch gern mein Muster überlassen, wenn Ihr mir den Hammer meines Vaters bringt.", completion = "Ich danke Euch, {name}.\n\nVielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[38521] = { id = 38521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tayla's Rescue - Reward" }
quests[38522] = { id = 38522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht nur Waffen und Rüstungen", description = "Ihr müsst wissen, dass wir uns nicht auf das Schmieden von Waffen und Rüstungen beschränken. Ich erhalte auch regelmäßig Anfragen nach Meißeln für Schreiber, Tiegeln für Alchemisten und sogar Fingerhüten für Schneider.\n\nWarum nähen sie nicht einfach mit Plattenhandschuhen, wenn sie sich so sehr um ihre armen kleinen Däumchen fürchten?\n\nAuf jeden Fall habe ich einen Plan, der für Abenteurer wie Euch interessant sein könnte. Probieren wir ihn aus.", sourceObjective = "Stellt 4 Hartleysteinbarren und 24 Hartleysteinnägel her.", progress = "An die Arbeit. Das wird Euch sicher gefallen.", completion = "Lasst mich einen Blick auf diese Barren werfen und ein paar Anpassungen vornehmen...\n\nTadaa! Hufplatten für Euer Reittier!", sourceObjectiveStatus = "unverified-source-field" }
quests[38523] = { id = 38523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leysteinhufplatten", description = "Hier, bringt diese Hufplatten zu Mei Francis unten beim Laden für Reit- und Haustiere, damit Euer Reittier ordentlich beschlagen wird.\n\nIch gebe Euch das Muster, wenn Ihr zurückkehrt.", sourceObjective = "Sucht Mei Francis in Dalaran auf, während Ihr auf Eurem Reittier sitzt, damit das Tier mit Leysteinhufplatten beschlagen wird.", completion = "Jetzt, da Mei Euer Reittier mit den Platten ausgestattet hat, solltet Ihr sie zukünftig selber anbringen können.\n\nOh, und bevor ich es vergesse: Hier ist das Muster. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[38524] = { id = 38524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsschmiedin Nal'ryssa", description = "In Schmiedekreisen erzählt man sich, dass zwei Illidarischmiede an der dämonenverseuchten Front von Suramar sehr interessante Arbeit verrichten. Ich würde mir das ja gern selbst ansehen, aber \"dämonenverseuchte\" Landstriche sind mir ein bisschen zu exotisch.\n\nIch fertige die Rüstung nur. Tragen sollen sie andere.\n\nBei Euch sieht das allerdings anders aus. Ihr könntet nach Nal'ryssa Ausschau halten. Ich hörte, sie soll eine verflucht gute Schmiedin sein.", sourceObjective = "Sucht Teufelsschmiedin Nal'ryssa in Suramar auf.", completion = "Seid Ihr hier, um uns zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[38525] = { id = 38525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teil des Teams", description = "Ihr seid <ein Schmied/eine Schmiedin>?\n\n<Die Elfe betrachtet Euren Hammer.>\n\nUnd Ihr arbeitet immer noch mit Leystein? Dann kann ich Euch vielleicht weiterhelfen.\n\nEs gibt nicht viele vertrauenswürdige Verbündete hier draußen. Ihr habt ein freundliches Gesicht, aber vielleicht arbeitet Ihr ja trotzdem für die Dämonen. Ich kann es mir nicht leisten, Euch jetzt schon zu trauen.\n\nKommt erst wieder, wenn Ihr vor Dämonenblut trieft. Dann können wir über das Schmieden sprechen.", sourceObjective = "Tötet 40 Dämonen innerhalb der Teufelsseelenbastion.", completion = "Das sollte genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38526] = { id = 38526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiede unter Feuer", description = "Ihr habt keine Pläne für Stiefel?\n\nWurdet Ihr etwa von Tauren ausgebildet?\n\nDann Beeilung. Wir haben vielleicht nur ein paar Minuten, bis die Dämonen wieder angreifen. Hier ist ein Muster. Zeigt mir, wie Ihr arbeitet.", sourceObjective = "Stellt nach den Anleitungen von Teufelsschmiedin Nal'ryssa ein Paar Leysteinstiefel her.", progress = "Passt hier draußen an der Front gut auf Euch auf. Das ist nicht Euer Schmiedeladen in Eurer friedvollen, schwebenden Stadt.", completion = "Nicht übel, {class}. Ihr wisst den Hammer zu schwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38527] = { id = 38527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nal'ryssas Techniken", description = "Hört zu, {class}. Wir brauchen Schmiede wie Euch, die die Traditionen der Illidari fortführen, falls unser Kreuzzug gegen die Legion scheitern sollte. Ihr seid bereit, diese Kunst zu erlernen.\n\nBringt mir Materialien. Und zwar jede Menge. Wenn Ihr zurückkommt, haben wir viel zu besprechen.", sourceObjective = "Sammelt 60 Brocken Leysteinerz und 60 Brocken Teufelsschiefer.", progress = "Seid Ihr bereit zu lernen?", completion = "Gut. Dann begeben wir uns an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[38528] = { id = 38528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Potenzial von Leystein", description = "Wie Ihr sicher bereits bemerkt habt, können all die Leysteinpläne, die Ihr erlernt habt, noch weiter verbessert werden.\n\nWenn man erlernt, wie man das wahre Potenzial des Leysteins ausnutzt, kann man den Materialverbrauch verringern und dennoch ein ähnliches Ergebnis erhalten.\n\nWir beginnen wie üblich mit einfachen Armschienen. Dieses Rüstungsteil lässt sich besonders gut mit Schwefelrunen verbessern. Hier, seht selbst.", sourceObjective = "Macht Euch Teufelsschmiedin Nal'ryssas Techniken zunutze, um ein Paar meisterliche Leysteinarmschützer herzustellen.", progress = "Macht weiter so, {class}.", completion = "Solide Arbeit.\n\nLeystein ist ein launisches Metall. Armschützer aus diesem Material lassen sich mit Schwefel verbessern, aber das gilt nicht für Schulterstücke. Dafür nimmt man Zauberstaub. Für Helme wiederum nimmt man ungeschliffene Edelsteine. Und so weiter und so fort...", sourceObjectiveStatus = "unverified-source-field" }
quests[38529] = { id = 38529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 023 - Weeping Bluffs - ZTO" }
quests[38530] = { id = 38530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Firmamentstein", description = "Wenn man mit Teufelsschiefer und Dämonenstahl arbeitet, benötigt man spezielles Werkzeug. Dazu gehört nicht zuletzt ein sehr harter Amboss, damit dieser der Energie standhalten kann, die abgegeben wird, wenn man auf Teufelsschiefer hämmert.\n\nUrael und ich besitzen solch einen Amboss nicht mehr. Aber Eure Freunde, die Hochbergtauren, haben einen.\n\nVerschafft Euch Zugang zum Firmamentstein, ihrem heiligen Amboss, und wir können die Arbeit mit Dämonenstahl wieder aufnehmen.", sourceObjective = "Sprecht mit Barm Steinbrecher auf dem Hochberg.", completion = "Ihr seid wieder da, {name}. Benötigt Ihr noch zusätzliche Ausbildung?\n\nWie bitte? Der Firmamentstein?\n\n\n\nDas ist eine ganz andere Angelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[38531] = { id = 38531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leysteinmeisterschaft", description = "Schmiede, die am Firmamentstein arbeiten wollen, müssen zunächst Zeugnis ihrer Leysteinmeisterschaft ablegen.\n\nStellt ein komplettes Leysteinrüstungsset her und reicht es dann zur Inspektion bei mir ein. Thala kann Euch mit einem Rüstungsständer versorgen.", sourceObjective = "Sprecht mit Thala Stahltotem, um einen Leysteinrüstungsständer zu erwerben, und hängt dann alle acht Leysteinrüstungsteile daran auf.", progress = "Und denkt daran, {name}: Nachlässige Arbeit toleriere ich nicht.", completion = "<Der Tauren schaut sich Eure Arbeit sorgfältig an und zieht dabei die Augenbrauen hoch.>\n\nWie ich sehe, habt Ihr Einiges gelernt.\n\nSehr gut. Ihr wart erfolgreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[38532] = { id = 38532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Vom Sturm gehämmert", description = "Euer Hammer sieht nicht sonderlich stabil aus und würde wahrscheinlich bei einem Schlag gegen den Firmamentstein zerbrechen.\n\nDie alten Meisterschmiede der Vrykul waren für die Stärke ihrer Hämmer bekannt. So einen Hammer bekommen wir nur, wenn wir uns an den Ort begeben, an den die Vrykul gehen, wenn sie sterben: in den Seelenschlund.\n\nDie über dieses Reich herrschende Göttin heißt Helya. In ihrem Besitz finden sich zahlreiche Schmuckstücke, die die Toten mit sich brachten.\n\nWenn Ihr sie besiegt, könnt Ihr ihr vielleicht einen solchen Hammer abnehmen.", sourceObjective = "Begebt Euch zum Seelenschlund und bergt dort einen uralten Vrykulhammer.", progress = "Habt Ihr einen ergattern können?", completion = "<Barm untersucht den Hammer und dreht ihn langsam in seinen Händen.>\n\nJa! DAS ist ein Hammer!", sourceObjectiveStatus = "unverified-source-field" }
quests[38533] = { id = 38533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stammeswissen", description = "Zunächst braucht Ihr allerdings die richtigen Muster für Dämonenstahlrüstung. Zugang zum Stein lässt sich durch harte Arbeit und Ausdauer verdienen – der Zugriff auf unsere Rezepte ist allerdings auf vertrauenswürdige Mitglieder unseres Stammes beschränkt.\n\nVielleicht solltet Ihr einen anderen Schmied aufsuchen, wenn Ihr über Dämonenstahlmuster sprechen möchtet.", sourceObjective = "Meldet Euch bei Teufelsschmiedin Nal'ryssa in Suramar.", completion = "Ich glaube nicht, dass die Tauren sich so leicht von ihren Rezepten trennen werden. Wir sind nicht ganz so... sturköpfig wie sie, aber selbst unsere Rezepte haben ihren Preis.\n\nImmerhin habt Ihr Euch das Recht auf Zugang zum Firmamentstein erworben und so den Weg zu einem anderen großartigen Amboss aufgezeigt, sollten Urael und ich ihn je benötigen.\n\nIhr habt Euch dieses Rezept als Zeichen unserer Dankbarkeit verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[38534] = { id = 38534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenstahlarmschützer", sourceObjective = "Ihr habt da ein Paar beeindruckende Armschützer hergestellt, aber Ihr könnt eine ebenso große Schutzwirkung erreichen, ohne so viel Rohmaterial zu verwenden.\n\nIch will es Euch zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38535] = { id = 38535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brimbil's Journey" }
quests[38536] = { id = 38536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenstahltaillenschutz", sourceObjective = "Das ist ausgezeichnete Schmiedearbeit.\n\nUnd jetzt will ich Euch einen Trick zeigen, wie man die Ressourcen schont.", sourceObjectiveStatus = "unverified-source-field" }
quests[38537] = { id = 38537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenstahlschulterstücke", sourceObjective = "Eure Arbeit mit dem Hammer ist makellos, aber der Plan, den Ihr verwendet, verlangt nach unnötig vielen Ressourcen.\n\nVersucht es einmal mit diesem hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[38538] = { id = 38538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenstahlstiefel", sourceObjective = "Wir fertigen hier üblicherweise nicht allzu viele Stiefel an, aber selbst ich kann sehen, dass Ihr viel zu viel Material für die Sohlen verwendet habt.\n\nHier sind ein paar Ratschläge, wie Ihr ressourcenschonender arbeitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[38539] = { id = 38539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenstahlstulpen", sourceObjective = "Die Illidari verstehen sich wirklich darauf, gutes Erz zu verschwenden, was?\n\nIhr solltet sie lieber auf diese Weise schmieden. Dafür werdet Ihr mir noch dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[38540] = { id = 38540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenstahlhelm", sourceObjective = "Sagt Thala und Barm nichts davon, aber ich habe hier noch ein paar Muster für Helme herumliegen... nur zu Belustigungs- und Dekorationszwecken, versteht sich.\n\nSchaut Euch das hier an. Selbst unter Einsatz weit weniger Rohstoffe bekommt Ihr viel bessere Ergebnisse.", sourceObjectiveStatus = "unverified-source-field" }
quests[38541] = { id = 38541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenstahlbeinschützer", sourceObjective = "Ihr habt es Euch leicht gemacht, aber versucht es einmal auf andere Weise.\n\nEs ist ein bisschen schwieriger, aber dafür spart Ihr jede Menge Material ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[38542] = { id = 38542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenstahlbrustplatte", sourceObjective = "Die Menge an Material, die Ihr für dieses Muster aufwendet, ist schlicht inakzeptabel. Wir müssen sparen, wo wir nur können. Das ist besser für das Land und für die Geldbörse.\n\nVerwendet lieber diese Pläne hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[38543] = { id = 38543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Armguards" }
quests[38544] = { id = 38544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Waistguard Crafted" }
quests[38545] = { id = 38545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Pauldrons Crafted" }
quests[38546] = { id = 38546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Boots Crafted" }
quests[38547] = { id = 38547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Gauntlets Crafted" }
quests[38548] = { id = 38548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brimbil's Journey - Reward" }
quests[38549] = { id = 38549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Helm Crafted" }
quests[38550] = { id = 38550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Greaves Crafted" }
quests[38551] = { id = 38551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Breastplate Crafted" }
quests[38552] = { id = 38552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Hal'sharas Grabmal", description = "Das Grabmal! Ich habe es gefunden!", sourceObjective = "Plündert das Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[38557] = { id = 38557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Invasion Point: Devastation" }
quests[38558] = { id = 38558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Elstern", description = "Diese kieferlosen Wichte versuchen, Teile unseres Schiffes zu bergen! Die können doch gar nicht mit unserer überragenden gnomischen Technologie umgehen... Vielleicht werden sie einfach nur von dem Glitzerkram angezogen.\n\nAuf jeden Fall benötige ich einen Kristalloszillator für unseren neuen Transponder. Das ist das glitzerndste Teil von allen. Den haben sie ganz sicher schon beiseite geschafft!", sourceObjective = "Stellt den Kristalloszillator sicher.", progress = "Habt Ihr den Oszillator gefunden?", completion = "<Oberfunks untersucht sorgfältig den Kristall.>\n\nJa, glitzert immer noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[38559] = { id = 38559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Steines würdig", description = "Es gibt nichts mehr, das Ihr mir noch beweisen müsst, {name}. Eure Ausbildung ist beendet.\n\nNur sehr wenige Schmiede haben sich den Zugang zum Firmamentstein verdient. Muirn Eisenhorn wacht über unseren heiligen Stein. Ihr solltet mit ihm sprechen. Er kann Euch sagen, was als Nächstes zu tun ist.", sourceObjective = "Sprecht mit Muirn Eisenhorn.", completion = "Ein neues Gesicht? Es muss Jahre her sein...\n\nDies ist der Firmamentstein. Prägt Euch seine Form ein, erspürt seine Faszination. Wenn Ihr tatsächlich Eure Schmiedekünste auf ein neues Niveau heben wollt, dann werdet Ihr ganz sicher viel Zeit mit ihm verbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38560] = { id = 38560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Fluch des Blutenden Auges", description = "Kommandant, wo wir nun die Zeit hatten, Späher in den ganzen Dschungel zu entsenden, haben wir Neuigkeiten aus der Nähe von Zeth'Gol.\n\nAnscheinend pflegt noch jemand eine Blutrache gegen das Blutende Auge und... ähm... macht Jagd auf sie. Die Jäger des Blutenden Auges kommen diesem Meuchler immer näher.\nIhr kennt ja das Sprichwort: \"Der Feind meines Feindes...\" Wir sollten uns ihre Fährtenleserkarten besorgen und versuchen, diesen Jäger vor ihnen zu finden.", sourceObjective = "Sammelt die Fährtenleserkarten, um den Aufenthaltsort des Schlächters zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[38561] = { id = 38561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Hexenmeister", description = "Kommandant, Ihr habt Besuch. Einer von Gul'dans Hexenmeistern hat sich unserer Basis genähert und sich ergeben. Er sagt, er hat Informationen über ein schreckliches Ereignis, das bald eintreten soll.\n\nIch schlage vor, dass Ihr sofort mit ihm sprecht.", sourceObjective = "Sprecht mit dem Hexenmeister in der Löwenwacht im Tanaandschungel.", completion = "Ich kam zu spät, um Euch die Nachricht rechtzeitig zu überbringen. Es tut mir wirklich leid. Diese armen Schamanen... Wenn ich es nur früher gewusst hätte!\n\nGul'dan hat alles für sein Ritual vorbereitet. Er wird die Litanei und seine eigene Teufelsmagie einsetzen, um einen Elementarlord zu verderben. Er will ihn dann dazu bringen, die Elementarverbindung zum Land zu trennen. Das wird einen gewaltigen Aufruhr in ganz Draenor nach sich ziehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[38562] = { id = 38562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Sargerei", description = "Die Auchenai berichten schon seit einiger Zeit, dass seit dem ersten Überfall von Teron'gor etwas mit Auchindoun nicht stimmt. Jetzt haben plötzlich die Sargerei angegriffen und ein Loch in eines der Kellergewölbe gesprengt.\n\nAus diesem Loch strömt nun Verderbnis, und wir müssen sie aufhalten.", sourceObjective = "Sucht nach der Quelle der Verderbnis unter Auchindoun und bringt sie zum Versiegen.", completion = "Noch mehr Seelen meiner Vorfahren wurden von Blutschatten geplündert! Das muss ein Ende haben, ein für alle Mal. Blutschatten muss erledigt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[38563] = { id = 38563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blumenpflücker und Tränkeschlucker", description = "Da wir jetzt wissen, dass Fuchsblumenfluxus sicher verwendbar ist, können wir auch Vorräte davon anlegen. Ich selbst habe aber keine besondere Lust auf Blumenpflücken. Ihr vielleicht? Auch nicht, oder?\n\nSprecht mit den Alchimisten und den Kräuterkundlern am Weg. Ich bin sicher, wir können irgendeine Vereinbarung für einen Arbeitsauftrag finden.", sourceObjective = "Sprecht mit Linzy Schwarzbolz und Kuhuine Sanftschreiter, um einen Arbeitsauftrag für Fuchsblumenfluxus auszuhandeln.", completion = "Da jetzt alles geklärt wäre, können wir weiter an der Verbesserung unserer Pläne arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[38564] = { id = 38564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gutes Geschäft", description = "Beim Durchgehen dieser Aufzeichnungen bin ich auf eine interessante Methode gestoßen, die Ihr für mich ausprobieren sollt.\n\nDabei muss das Metall noch während der Vorhärtungsphase auf Temperaturen unter Null abgekühlt werden. Das Ablöschen mit einfachem Wasser reicht da nicht aus.\n\nAber das Gute an dieser Stadt ist ja, dass man quasi ständig über einen Frostmagier stolpert! Versucht, einen von ihnen für unseren Laden zu rekrutieren, {name}.", sourceObjective = "Sucht nach einem Frostmagier in Dalaran, um Eure Löschwanne herunterzukühlen.", completion = "Gut gemacht, {name}. Dann wollen wir es mal ausprobieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[38565] = { id = 38565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sargereibedrohung", description = "Dieser Angriff hat unsere Verteidiger überrascht. Wir sammeln unsere Streitkräfte, um sie zurückzuschlagen, doch wird es einige Zeit dauern, bis sie hier sind.\n\nMit jedem Sargerei, den Ihr töten könnt, wird die Rückeroberung dieses Gebiets wesentlich einfacher, Kommandant.", sourceObjective = "Tötet 12 Sargerei.", sourceObjectiveStatus = "unverified-source-field" }
quests[38566] = { id = 38566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinte Macht", description = "Die Paladine von Azeroth müssen alle hinter einem einzigen Anführer stehen. Nach Tirions Ableben seid Ihr am würdigsten, den Titel Hochlord zu tragen.\n\nWenn Ihr Euch bereit erklärt, diese Aufgabe zu übernehmen, schreibt Euren Namen in den Buchband der Uralten Könige, dann werde ich in Eurem Namen vor den Anwesenden sprechen.\n\nDer Orden der Silbernen Hand wird wieder zum Leben erweckt, mit Euch als Champion!", sourceObjective = "Begründet den Orden der Silbernen Hand mithilfe des Buchbands der Uralten Könige.", progress = "Ja, Hochlord?", completion = "Wir haben es vollbracht, Hochlord {name}.\n\nDer Orden der Silbernen Hand ist neu geboren!", sourceObjectiveStatus = "unverified-source-field" }
quests[38567] = { id = 38567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Kriegsrat", description = "Eure Garnison befindet sich in Aufruhr. Kriegshäuptling Vol'jin persönlich ist zu Besuch in Eurer Festung, um über die Invasionspläne für den Tanaandschungel zu sprechen.\n\nDer Kriegshäuptling wartet auf Euch im Hauptgebäude. Es wäre klug, ihn nicht allzu lange warten zu lassen...", sourceObjective = "Sprecht mit Kriegshäuptling Vol'jin im Hauptgebäude Eurer Garnison.", completion = "<Der Kriegshäuptling studiert mit sorgenvoller Miene eine Karte des Tanaandschungels und der umgebenden Gebiete.>\n\nAh, Kommandant {name}! Die Stimme der Horde in Draenor. Ihr habt Eure Sache hier gut gemacht und unseren Feinden mächtig zugesetzt. Thrall sagt, Ihr übertrefft seine kühnsten Erwartungen.\n\nEs wird Zeit, die Sache zu beenden. Seid Ihr bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[38568] = { id = 38568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffsbauer gesucht", description = "Der Rest der Eisernen Horde hat sich zum Tanaandschungel zurückgezog'n, wo Gul'dan etwas noch viel Übleres aus ihnen macht. Ein direkter Angriff wäre Selbstmord.\n\nAber die Seewege sind noch off'n. Wenn wir sie gleichzeitig zu Land und zu See angreif'n, muss Gul'dan sich noch weiter zurückzieh'n. {name}, wir müssen jetzt 'ne Schiffswerft aufbauen!\n\nWir brauch'n die Ressourcen vor Ort. Begebt Euch zu den Eisendocks. Die Jungs von Gazlowe sind bereits da. Sammelt so viel Ausrüstung zusamm'n wie möglich und findet 'nen Schiffsbauer, der 'ne Flotte für die Horde bau'n kann!", sourceObjective = "Begebt Euch zu den Eisendocks und sprecht mit Sammy Stibitz. Der Flugmeister Eurer Garnison kann Euch dorthin bringen.", completion = "Kommandant! Ich hatte gehofft, dass Verstärkung kommt. Hier ist alles außer Kontrolle. Die Eiserne Horde hat sich aus der Schmiede zurückgezogen und nutzt auf Gul'dans Befehl hin jetzt diese Docks, um nach Tanaan zu fliehen.\n\nAber meine Leute haben etwas gefunden, was Euch nützlich sein könnte, wenn Ihr schnell genug seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[38569] = { id = 38569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung der Docks", description = "Wir müssen diese Situation unter Kontrolle bekommen. Wir dachten, diese Docks wären vollkommen verlassen. Tatsächlich aber hat Gul'dan der Eisernen Horde befohlen, sich nach Tanaan zurückzuziehen. Und viele von ihnen nutzen diese Hafen, um von hier zu entkommen.\n\nWir müssen unserem Bergungsteam den Weg freimachen. Tötet sie alle! Alle Gegner, die wir hier abschlachten, stehen dann Gul'dan nicht mehr für seine widerwärtige Dämonenarmee zur Verfügung.", sourceObjective = "Tötet 1 Orcs der Eisernen Horde und 50 Ogron.", sourceObjectiveStatus = "unverified-source-field" }
quests[38570] = { id = 38570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entgleisung", description = "Einige Orcs haben ihre Stimme gegen Gul'dan erhoben und wurden dafür ins Gefängnis gesteckt. Unter ihnen ist auch eine Ingenieurslegende: Solog Roark, \"Der Eiserne Schiffsbauer\". Er ist wirklich gut. Er hat sowohl diese Docks entworfen als auch die großen Schlachtschiffe, die bei der Schlacht um Shattrath zum Einsatz kamen.\n\nWenn meine Späher richtig liegen, ist er zurzeit in einem Gefängniszug eingekerkert... Und ich wette, dass er bereit ist, die Seiten zu wechseln!\n\nSammelt Sprengladungen zusammen und trefft Euch mit Durotan beim Zug im Süden!", sourceObjective = "Sammelt Sprengladungen und einen Zünder.", progress = "Ihr seid es, Kommandant! Sehr gut! Ich brauche jemanden, auf den ich mich verlassen kann.", completion = "Wir konnten bestätigen, dass Solog Roark in diesem Gefängniszug ist. Aber er ist fest verschlossen. Oh, Ihr habt Sprengladungen mitgebracht? Hm, Eure Goblinfreunde denken ja wirklich an alles.\n\nDann lasst uns jetzt diese Kiste aufbrechen und diesen Schiffsbauer davon überzeugen, sich uns anzuschließen...", sourceObjectiveStatus = "unverified-source-field" }
quests[38571] = { id = 38571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugüberfall", description = "Meine Krieger werden den Waggon umstellen und Deckung geben. Aktiviert den Zünder, um die Türen aufzusprengen.\n\nIch werde mit Roark sprechen und ihn davon überzeugen, sich uns anzuschließen. Er hat all das hier aufgebaut. Er könnte uns helfen, eine eigene Werft in Betrieb zu nehmen.\n\nAber wenn die Sache nicht funktioniert, müsst Ihr ihn sofort töten. Das Letzte, was wir brauchen, ist jemand, der die Eiserne Flotte wieder aufbaut.", sourceObjective = "Verwendet den Zünder, um die Tür des Waggons aufzusprengen, und überzeugt dann Roark davon, die Seiten zu wechseln.", completion = "Steckt die Waffe weg. Schwarzfaust ist tot und unser neuer \"Kriegshäuptling\" hat gerade mein Todesurteil unterschrieben. Ich werde wohl von nun an ein Söldner sein.\n\nIhr wollt eine eigene Schiffswerft aufbauen? Dann braucht Ihr meine Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[38572] = { id = 38572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Mann klar zum Meucheln", description = "Ich kann Euch eine Schiffswerft aufbauen. Und das wird nicht so eine selbstgefällige, kindliche Ingenieursfantasie wie dieser Ort hier.\n\nAber dazu benötige ich meine Pläne. Meine Arbeiten wurden konfisziert, als Gul'dan diesen Hafen Admiral Knar übergab.\n\n<Roark spuckt aus.>\n\nGul'dans grünes Gift fließt durch Knars Adern. Von dort oben aus hat er jetzt alles unter Kontrolle. Wir müssen da hoch klettern und ihn ausschalten.", sourceObjective = "Verwendet einen Schwarzfelsgreifer, um auf Knars Bunker zu gelangen. Schaltet ihn aus und nehmt ihm Roarks Werftbaupläne ab.", progress = "Ich werde eine Werft für Euch bauen.", completion = "<Solog Roark wirft einen letzten Blick auf den Hafen.>\n\nAll das haben wir umsonst aufgebaut, {class}. Gul'dan wird sich nehmen, was Eure Truppen nicht zerstört haben.\n\nNächstes Mal werde ich etwas bauen, was von Dauer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[38573] = { id = 38573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles vergeht", description = "Hier gibt es nichts mehr für mich. Meine alten Klangefährten sind meine Feinde geworden und Gul'dan zieht alles in den Dreck, was noch von meinem Volk übrig ist.\n\nIhr und Eure Gefährten von den Frostwölfen habt noch genug Courage, um zu kämpfen. Wenn Ihr gelobt, Gul'dan zur Strecke zu bringen, werde ich Euch unterstützen. Ich werde Eure Garnison aufsuchen und zusammen bauen wir eine Schiffswerft auf, mit deren Hilfe wir die roten Meere von Draenor beherrschen werden!\n\nSagt Euren Leuten, dass ich mich auf den Weg mache.", sourceObjective = "Meldet Euch bei Vol'jin in Eurer Garnison.", completion = "Ihr habt einen Schiffsbauer gefunden? Sehr gut! Einige Eurer Anhänger können es gar nicht erwarten, in See zu stechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38574] = { id = 38574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Mann an Deck", description = "Dann wollen wir diesen \"Eisernen Schiffsbauer\" mal an die Arbeit gehen lassen, Kommandant. Wenn wir Tanaan zeitgleich von Land- und Seeseite aus angreifen wollen, brauchen wir eine Schiffswerft. Arbeitet mit Roark zusammen, damit wir so was bekommen!\n\nEr kundschaftet gerade das Gebiet entlang der Straße westlich des Frostwalls aus.", sourceObjective = "Errichtet eine Werft der Stufe 1 für Eure Garnison.", progress = "Ich brauche Baumaterialien, Kommandant. Man kann keine Docks aus Eis und Schnee bauen.", completion = "<Solog Roark sucht den Horizont mit den Augen ab.>\n\nDas sollte funktionieren. Das ist ein guter Tiefwasserhafen. Wir können das alte Kriegsschiff ausschlachten und zu einem Transportschiff umbauen. Die Materialien diese Klippen hier hoch und runter zu schleppen, wird eine elende Schinderei, aber im Falle eines Angriffs sind wir hier geschützt.\n\nDas kriegen wir hin. Seid Ihr bereit für den Baubeginn?", sourceObjectiveStatus = "unverified-source-field" }
quests[38576] = { id = 38576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen am Hoffnungsvollen Licht", description = "Mit Euch an unserer Seite wird die Legion fallen, dessen bin ich gewiss! Doch bevor wir zu den Verheerten Inseln ziehen, müssen wir Hochlord Tirion zur Ruhe betten.\n\nFür einen Paladin seines Kalibers ist nur ein Ort geeignet: das Sanktum des Hoffnungsvollen Lichts, eine geheime Bastion des Lichts, die unter unserer Kapelle verborgen liegt.\n\nPaladine aus aller Welt sind auf dem Weg, um an der Zeremonie teilzunehmen. Aber Euer Beisein hätte Tirion mehr bedeutet, als das aller anderen.", sourceObjective = "Trefft Euch mit den anderen Paladinen im Sanktum des Hoffnungsvollen Lichts unter der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", completion = "Eure Teilnahme hier ist wahrlich mehr als angemessen.\n\nEin ums andere Mal habt Ihr unsere Welt gerettet. Und jetzt, fürchte ich, muss ich Euch um einen noch größeren Dienst bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[38577] = { id = 38577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um den Westen", description = "Unsere Basis ist kaum fertiggestellt, und schon richtet die Eiserne Horde eine Verteidigungslinie gegen uns ein. Der Plan hat funktioniert, und wir kämpfen an zwei Fronten.\n\nIch habe erfahren, dass Durotan endlich die westlichen Tore durchbrochen hat, aber in einer offenen Schlacht feststeckt. Ihr solltet gehen, um die Situation persönlich zu beurteilen.", sourceObjective = "Geht an die Eiserne Front und sprecht mit Durotan.", completion = "Jetzt seht Ihr selbst, was hier gegen uns steht. Wir werden den Druck hier so gut wie möglich aufrechterhalten, um Eure Basis abzuschirmen, damit Ihr im ganzen Dschungel angreifen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38578] = { id = 38578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nachricht von furchtbarer Dringlichkeit", description = "Euer Späher... Er hat mich aus diesem teuflischen Ort befreit. Höllenorcs haben uns im Dschungel überrascht und uns den Berg hochgeschleift. Sie haben uns gefoltert... Sie haben alle getötet... außer mir. Ich befürchte, dass einer von uns unsere Geheimnisse verraten haben könnte, bevor es vorbei war.\n\nIch muss Euch bitten, die Heimat unseres Ordens aufzusuchen. Sprecht mit Lagar, meinem Anführer. Sagt ihm... Sagt ihm, dass Gul'dan Bescheid weiß.", sourceObjective = "Geht zum Erdgewölbe und sprecht mit Lagar dem Weisen.", completion = "Wir werden uns später weiter darüber unterhalten, aber vielen Dank erst einmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[38579] = { id = 38579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Xanzith the Everlasting" }
quests[38580] = { id = 38580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Overlord Ma'gruth" }
quests[38581] = { id = 38581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um den Westen", description = "Unsere Basis ist kaum fertiggestellt, und schon richtet die Eiserne Horde eine Verteidigungslinie gegen uns ein. Der Plan hat funktioniert, und wir kämpfen an zwei Fronten.\n\nIch habe erfahren, dass Exarch Maladaar endlich die westlichen Tore durchbrochen hat, aber in einer offenen Schlacht feststeckt. Ihr solltet gehen, um die Situation persönlich zu beurteilen.", sourceObjective = "Geht an die Eiserne Front und sprecht mit Exarch Maladaar.", completion = "Jetzt seht Ihr selbst, was hier gegen uns steht. Wir werden den Druck hier so gut wie möglich aufrechterhalten, um Eure Basis abzuschirmen, damit Ihr im ganzen Dschungel angreifen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38582] = { id = 38582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf alte Freunde", description = "Ich spüre die Anwesenheit einer dunklen Macht, {name}, aber es ist nicht Xavius. Es fühlt sich viel zu vertraut an.\n\nEs ist die Nähe eines Druiden, der vom Schatten des Alptraums verderbt wurde.\n\nWir müssen uns dieser Bedrohung stellen, wenn wir Xavius finden wollen. Ich werde in die Lüfte aufsteigen und Euch von oben unterstützen.\n\nFindet den verderbten Druiden und macht seinen bösartigen und pervertierten Plänen ein Ende.", sourceObjective = "Tötet 50 verderbte Kreaturen in Mondruh.", completion = "Seid versichert, {name}. Ihr habt das einzig Mögliche getan.\n\nIst ein Sterblicher erst einmal dem Alptraum anheimgefallen, gibt es kein Zurück. Nur der Tod bringt dann noch die Erlösung.", sourceObjectiveStatus = "unverified-source-field" }
quests[38583] = { id = 38583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Group - Throne of Kil'jaeden" }
quests[38584] = { id = 38584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Group - Throne of Kil'jaeden" }
quests[38585] = { id = 38585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Kil'jaedens Thron", description = "Der Schattenrat hat seine Dämonenmeister auf einem Berg zusammengerufen, den sie \"Kil'jaedens Thron\" nennen. Seid auf der Hut – das ist das gefährlichste Gebiet in ganz Tanaan.\n\nStellt eine Kampftruppe zusammen und greift Kil'jaedens Thron an, bevor die Legion sich hier einnisten kann!", sourceObjective = "Vernichtet die Truppen des Schattenrats auf Kil'jaedens Thron im Tanaandschungel.", completion = "Willkommen zurück, Kommandant. Unsere Späher haben uns bereits von Euren Erfolgen berichtet.\n\nGut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[38586] = { id = 38586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Kil'jaedens Thron", description = "Der Schattenrat hat seine Dämonenmeister auf einem Berg zusammengerufen, den sie \"Kil'jaedens Thron\" nennen. Seid auf der Hut – das ist das gefährlichste Gebiet in ganz Tanaan.\n\nStellt eine Kampftruppe zusammen und greift Kil'jaedens Thron an, bevor die Legion sich hier einnisten kann!", sourceObjective = "Vernichtet die Truppen des Schattenrats auf Kil'jaedens Thron im Tanaandschungel.", progress = "Wie verläuft der Angriff, General?", completion = "Die Späher haben schon von Euren Erfolgen berichtet.\n\nLok'tar!", sourceObjectiveStatus = "unverified-source-field" }
quests[38587] = { id = 38587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Kil'jaedens Thron", description = "Der Schattenrat hat seine Dämonenmeister auf einem Berg zusammengerufen, den sie \"Kil'jaedens Thron\" nennen. Denkt zurück an den Ersten Krieg: Wir wissen, welche Verheerungen die Legion anrichten kann, wenn sie nicht rechtzeitig aufgehalten wird.\n\nBegebt Euch zu Kil'jaedens Thron und macht dieser Invasion ein Ende, bevor sie überhaupt richtig beginnt.", sourceObjective = "Greift die Truppen des Schattenrats auf Kil'jaedens Thron im Tanaandschungel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[38588] = { id = 38588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Kil'jaedens Thron", description = "Der Schattenrat hat seine Dämonenmeister auf einem Berg zusammengerufen, den sie \"Kil'jaedens Thron\" nennen. Wir wissen, welche Verheerungen die Legion anrichten kann, wenn sie nicht rechtzeitig aufgehalten wird.\n\nBegebt Euch zu Kil'jaedens Thron und macht dieser Invasion ein Ende, bevor sie überhaupt richtig beginnt.", sourceObjective = "Greift die Truppen des Schattenrats auf Kil'jaedens Thron im Tanaandschungel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[38589] = { id = 38589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Ravager Broodlord" }
