quests[38593] = { id = 38593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ravager Spear" }
quests[38594] = { id = 38594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.2 Tanaan Max-level Choice Reward Summary: Group" }
quests[38595] = { id = 38595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurions Zorn", description = "Dass wir Cenarius an den Alptraum verloren haben, ist ein furchtbarer Schlag für uns alle.\n\nMalfurions Wut mag gerechtfertigt sein, aber sein Hass auf Xavius schwelt seit Jahrhunderten. Ich fürchte, dass jemand seine blinde Wut gegen ihn selbst richten wird.\n\nMöge Elune uns auf der Suche nach ihm leiten, auf dass wir heute nicht noch einen weiteren Freund betrauern müssen.", sourceObjective = "Sprecht mit Ysera, um nach Malfurion zu suchen.", completion = "Oh, {name}...\n\nWas wird nur aus diesem kostbaren Land?", sourceObjectiveStatus = "unverified-source-field" }
quests[38596] = { id = 38596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TRACKING Nightmare 02" }
quests[38597] = { id = 38597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Panther Saberon Boss" }
quests[38598] = { id = 38598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEST: Craft Some Legplates", description = "Die Hochbergtauren stellen ihre Beinplatten Stück für Stück her und setzen sie dann am Ende zusammen.\n\nDas scheint mir eine ziemlich müßige und langwierige Methode zu sein, aber wir sollten damit anfangen, bevor wir uns irgendwelche Verbesserungen in puncto Effizienz überlegen.\n\nHier ist etwas Leystein. Ich habe die Pläne auch in Eure Arbeitsmappe eingetragen. Versucht es einfach mal!", sourceObjective = "Macht Gebrauch von Euren Schmiedefertigkeiten und stellt ein Paar handgefertigte Leysteinbeinplatten her.", sourceObjectiveStatus = "unverified-source-field" }
quests[38599] = { id = 38599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infrastrukturmaßnahmen", description = "So, <mein Herr/meine Dame>, wir haben Euch jetzt ein Luftfahrzeug zusammengebaut, um Euch hoch auf Kil'jaedens Thron zu bringen. Aber bis jetzt sind bei jedem Testflug die Navigationssysteme ausgefallen!\n\nAls Experte in diesen Dingen vermute ich, dass das an dieser verrückten Dämonenmagie liegt, mit der die Eiserne Horde da oben herumspielt.\n\nWenn Ihr aber ein paar dieser Telemetrieantennen in der Gegend da oben aufstellen könntet, wären wir in der Lage, das Luftfahrzeug umzuprogrammieren und Euch einen sicheren Flug zu gewährleisten.\n\nUnd nehmt besser ein paar Freunde mit. Die Dämonen da oben sehen ganz besonders garstig aus!", sourceObjective = "Platziert 5 Telemetrieantennen G-X3.", completion = "Willkommen zurück! Die Signale kommen ganz deutlich rein und das Fluggerät ist bereit zum Start!\n\nWenn Ihr wieder nach da oben wollt, dann nehmt einfach die Rakete als schnellstes Transportmittel in ganz Draenor! Wir haben sie gleich neben Gargash bereitgestellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38600] = { id = 38600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Fel Saberon Shaman" }
quests[38601] = { id = 38601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Saberon Supplies" }
quests[38602] = { id = 38602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Fel Spike" }
quests[38603] = { id = 38603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signalplatzierung", description = "So, <mein Herr/meine Dame>, wir haben Euch jetzt ein Luftfahrzeug zusammengebaut, um das Lager der Horde zu umgehen und Euch hoch auf Kil'jaedens Thron zu bringen. Aber da gibt es ein Problem: Aufgrund der konzentrierten Teufelsenergie da oben spielen die Navigationssysteme verrückt!\n\nIhr müsstet ein paar Sensoren in der Gegend um den Gipfel herum platzieren. Nur mit ihrer Hilfe können wir die erforderliche Flugstabilität erzielen.\n\nUnd nehmt besser ein paar Freunde mit. Die Dämonen da oben sehen ganz besonders garstig aus!", sourceObjective = "Platziert 5 Pentangulier-o-Trons 2000.", completion = "Willkommen zurück! Die Signale von den Sensoren kommen ganz deutlich rein und der Crew ist es gelungen, sie an die Navigationssysteme zu koppeln. Damit sollten wir startklar sein!\n\nWir haben die Maschine gleich neben Himmelswache Thann bereitgestellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38604] = { id = 38604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Saberon Shaman" }
quests[38605] = { id = 38605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Saberon Blademaster" }
quests[38607] = { id = 38607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pforte der Tapferkeit", description = "Helyas Fängen ungeschoren zu entkommen, ist keine Selbstverständlichkeit. Vielleicht seid Ihr tatsächlich <ein würdiger Krieger/eine würdige Kriegerin>.\n\nSkovald hat die Hallen der Tapferkeit bereits betreten. Euch bleibt nicht mehr viel Zeit. Skovalds Männer sind bereits von der Legion verderbt worden. Ein Bataillon unwürdiger Vrykul versucht, das Portal zu den Hallen der Tapferkeit zu betreten.\n\nDie Riesen, die die Tore bewachen, scheinen den Kampf zu verlieren. Der Ansturm der Legion ist nicht aufzuhalten.\n\nSprecht mit Vedhir, dem Drachen bei den Toren in der Nähe des Portals. Er wird Euch bei Eurer nächsten Aufgabe helfen.", sourceObjective = "Sprecht mit Vedhir.", sourceObjectiveStatus = "unverified-source-field" }
quests[38609] = { id = 38609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Iron Tunnel Foreman" }
quests[38610] = { id = 38610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arauk Nashal 70:JP3 - Gates of Valhallas -Tracking quest - Titan Vehicle - Bonus Objective" }
quests[38611] = { id = 38611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille der Thorignir", description = "Wo die Stürme am heftigsten tosen, erwarten Euch die Drachen. Sie sind Nachkommen der Götter und werden Eure Willensstärke auf die Probe stellen.\n\nSie leben oberhalb von Hrydshal, wo ihre Kinder den Drekirjar dienen. Allerdings sind sie keine Verbündeten der Menschen oder der Vrykul. Daher müsst Ihr versuchen, ihre Gunst zu gewinnen.\n\nEine Freundin erwartet Euch in Hrydshal und ist zweifelsohne auf der Suche nach Antworten, die Ihr nun habt. Geht zu ihr und stellt Euch gemeinsam der Macht des Sturms!", sourceObjective = "Trefft Euch außerhalb von Hrydshal mit Schreckensreiterin Cullen, um mit der Prüfung der Thorignir zu beginnen.", completion = "Diese Vrykul sind so langweilig! Warum schickt Nathanos mich auf solche Missionen? Denkt er denn wirklich, dass die Aegis hier ist?\n\nIch hoffe, Ihr seid hierhergekommen, um für ein bisschen Ärger zu sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38612] = { id = 38612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifhaken abgreifen", description = "Also erhalten wir Hilfe von irgendeinem alten magischen Vrykul? Das klingt schon mal gut, aber Eure Prüfung könnte kniffelig werden. Seht Ihr, der einzige Weg auf den Berg führt durch diese hohen Mauern.\n\nJa, die mit den fies aussehenden Drachen oben drauf.\n\nIch habe mich schon ein wenig umgesehen, doch da diese Drachen die arme Herzogin als Mittagessen auserkoren haben, kam ich nicht weit. Die Vrykul haben sie trainiert und das verheißt nichts Gutes.\n\nIch sage, wir schleichen uns rein. Ich habe mir schon ein paar Greifhakenwerfer besorgt. Nehmt Euch einen und trefft mich außerhalb der Stadtmauern.", sourceObjective = "Nehmt den sturmgeschmiedeten Greifhakenwerfer und trefft Euch mit Schreckensreiterin Cullen außerhalb der Mauern von Hrydshal.", completion = "Ja, damit sollten wir klarkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38613] = { id = 38613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer braucht schon Flügel?", description = "Das Ding scheint über genug Reichweite zu verfügen, um uns über die Mauer zu bringen. Es gibt dafür eine gute Stelle gleich hinter uns. Ihr solltet sie von hier aus schon sehen können.\n\nUnd wenn Ihr drinnen seid, tut mir einen Gefallen und lenkt die Wachen ab, damit ich mich vorbeischleichen kann. Ich versuche dann, etwas mehr über diese Vrykul herauszufinden.", sourceObjective = "Verwendet den sturmgeschmiedeten Greifhakenwerfer, um die Mauern von Hrydshal zu erklimmen.", completion = "Diese Vrykul waren so perplex, jemanden durch ihre Stadt fliegen zu sehen, dass sie mich gar nicht bemerkt haben. \n\nIch hoffe, Ihr habt nicht allzu viel ungewollte Aufmerksamkeit erregt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38614] = { id = 38614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wetterfeste Ausrüstung", description = "Ich habe hier ein bisschen herumgeschnüffelt und dabei festgestellt, dass diese Vrykul selbst öfter den Gebirgspfad beschreiten, den wir erklimmen wollen. Und sie haben dafür sogar spezielle Ausrüstung, die Ihr ihnen vielleicht abnehmen könnt.\n\nDa gibt es zum Beispiel Kletterschuhe für besseren Halt und gefettete Umhänge, um trocken zu bleiben. Und sie führen auch Steine bei sich, mit denen man der Gefahr durch Blitze Herr werden kann. So einen solltet Ihr Euch auch zulegen.", sourceObjective = "Sammelt Kletterschuhe, einen gefetteten Umhang und einen verzauberten Leitstein in Hrydshal.", progress = "Habt Ihr alle Ausrüstungsteile bekommen?", completion = "Von der Größe her nicht ganz passend, aber trotzdem brauchbar. \n\nDieser Pfad sieht nicht sehr einladend aus, also solltet Ihr gut vorbereitet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[38615] = { id = 38615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speerabwehr", description = "Die Naturgewalten scheinen nicht Eure einzigen Feinde auf dem Pfad da oben zu sein. Diese Harpunenschleudern sehen nämlich auch ganz schön garstig aus. Wenn wir die nicht ausschalten, können sie jeden aufspießen, der den Pfad erklimmen will.\n\nSie sind dort oben auf den Mauern, also müsst Ihr den Greifhakenwerfer benutzen, um sie zu erreichen. Passt nur auf, dass Ihr nicht als Drachenfutter endet!", sourceObjective = "Nutzt einen Greifhaken, um auf die Mauern von Hrydshal zu gelangen, und zerlegt 7 Harpunenschleudern der Wellenskorn.", completion = "Über diese Blechköppe müssen wir uns keine Gedanken mehr machen! \n\nAber offensichtlich hat unser Plan einen anderen Haken: Diese Brücke war der einzige Weg nach oben...", sourceObjectiveStatus = "unverified-source-field" }
quests[38616] = { id = 38616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuppe um Schuppe", description = "Die Vrykul in dieser Gegend scheinen ihre Rüstungen aus den Schuppen dieser Drachen herzustellen. \n\nWenn Ihr genug Material von den hiesigen Drachen zusammenbekommt, könnt Ihr vielleicht etwas Nützliches daraus machen.", sourceObjective = "Sammelt Sturmdrachenschuppen von den Sturmdrachen in Hrydshal ein.", progress = "Was haben wir denn hier?", completion = "Gute Idee: Wenn die Vrykul diese Drachenschuppen als Rüstung verwenden, könnten wir das doch auch?\n\nEs sollte nicht allzu schwer sein, daraus etwas Verwertbares zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38617] = { id = 38617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein anderer Weg", description = "Moment! Habt Ihr noch den Greifhakenwerfer? Wenn Ihr den von der Spitze des Turms abfeuert, könntet Ihr wohl immer noch den Pfad erreichen. Der Abstand scheint dort nicht allzu groß zu sein.\n\nAber natürlich müssen wir noch den großen Typen davor ausschalten. Der sieht übel aus, aber wir sollten das schaffen, wenn wir ihn von zwei Seiten angreifen.", sourceObjective = "Besiegt den Champion der Drekirjar in Hrydshal und steigt dann zur Spitze des Turms hoch.", progress = "Ein Kinderspiel!", completion = "Was für ein Kampf!\n\nUnd ich dachte schon, dieser Ort hier wäre todlangweilig!", sourceObjectiveStatus = "unverified-source-field" }
quests[38618] = { id = 38618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über dem Wintermondlicht", description = "Gleich da drüben scheint eine gute Stelle zum Abfeuern des Werfers zu sein. Auf diesem Pfad müsstet Ihr bis ganz nach oben kommen.\n\nLaut meinen Informationen findet Ihr da oben Eure Drachen. Ich hoffe nur, dass sie überhaupt noch in der Lage sind, Euch zu helfen.", sourceObjective = "Hangelt Euch vom Turm hinüber und steigt dann zum Gipfel des Gebirgspfads hoch.", completion = "Ihr seid wegen der Prüfung hier? Ich fürchte, dass Ihr zu spät seid.\n\nDieser Kampf mit den Teufelsskorn hat seine Spuren hinterlassen. Ich bin zu schwach, um Euch die gewünschte Kraft zu verleihen...\n\nAber vielleicht könnt Ihr mir helfen...", sourceObjectiveStatus = "unverified-source-field" }
quests[38620] = { id = 38620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Pale Assassin" }
quests[38624] = { id = 38624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donner des Schmerzes", description = "Ihr habt Euch als <würdiger Verbündeter/würdige Verbündete> der Thorignir erwiesen. Wir werden Euch unsere Stärke verleihen. Zuvor habe ich allerdings noch ein Anliegen an unseren neuen Champion.\n\nDer Drache, der Euch zu mir geführt hat, wartet nur darauf, blutige Rache an den Vrykul zu üben. Ich möchte, dass Ihr diesen Drekirjar gemeinsam zeigt, was es bedeutet, den Zorn der Thorignir zu wecken. Egal ob sie Teufelsskorn sind oder nicht, ihre Bosheit hat meiner Brut Leid zugefügt. Ihre Schuld muss mit Blut bezahlt werden.\n\nSprecht mit Vethir, wenn Ihr bereit seid.", sourceObjective = "Fliegt mit Vethir und tötet 150 Verbündete des Gottkönigs in Hrydshal.", completion = "<Der Rabe krächzt und Havis Stimme dringt in Euren Kopf.>\n\nDie Prüfung hat gezeigt, dass Ihr wahrhaft mächtig seid.\n\nDoch Heldenmut ist eine gänzlich andere Bestie, die es erst noch zu zähmen gilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38625] = { id = 38625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hook & Sinker" }
