quests[38632] = { id = 38632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Night Haunter" }
quests[38633] = { id = 38633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von brennender Wichtigkeit", description = "Champion, wenn ich Euch von den Schrecken berichten würde, die ich erblickt habe, würdet Ihr mir kein Wort davon glauben. Die Zeitlinie verdreht sich und ein düsteres Schicksal erwartet Euch. Die Kausalität lässt nach und in dieser düsteren Zukunft gehört Eure Treue dem Verräter selbst, Illidan Sturmgrimm. Begebt Euch in die Vergangenheit und rettet Euch selbst, doch habt acht – dort bleiben Euch nur Eure damaligen Kräfte.", sourceObjective = "Rettet Euch selbst, indem Ihr einen Zeitwanderungsdungeon abschließt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38634] = { id = 38634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Felsmith Damorka" }
