quests[38639] = { id = 38639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Swamp Blossom" }
quests[38640] = { id = 38640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Anti Pale Equipment" }
quests[38641] = { id = 38641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel von Elune", description = "Cenarius ist in Gefahr.\n\nWenn sich sein Zustand nicht bald bessert, verlieren wir ihn an den Alptraum, der den Smaragdgrünen Traum bedroht. Um ihn vor diesem Schicksal zu bewahren, brauchen wir die Tränen von Elune. Dasselbe Relikt, das Ihr hier beschaffen solltet.\n\nElunes Tempel ist nicht weit von hier. Begebt Euch dorthin und sucht nach Lyanis. Zeigt ihr mein Siegel und weist sie an, die Tränen in Eure Obhut zu übergeben.\n\nBeeilt Euch, {name}. Wir haben nicht viel Zeit.", sourceObjective = "Sprecht mit Lyanis Mondfall beim Tempel von Elune.\n\nBereitgestellter Gegenstand:", completion = "Ihr- Ihr tragt das Siegel der Träumerin. Elune sei gepriesen!\n\nIhr kommt gerade rechtzeitig, Reisender. Shaladrassils Wurzeln haben bereits die Schwelle unseres Tempels erreicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[38642] = { id = 38642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vrykul Longboat" }
quests[38643] = { id = 38643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dorf in Gefahr", description = "Der Leichnam von Darcy Heathrow liegt vor Euch, von Pfeilen durchbohrt und mit Stichwunden übersät.\n\nIn einer Hand umklammert sie eine Notiz, die sie mit letzter Kraft verfasst hat:\n\n\"Die Toten marschieren nach Bradenbach.\n\nBitte helft uns!\"", sourceObjective = "Sprecht mit Bürgermeister Heathrow in Bradenbach.", completion = "Wir brauchen keine Hilfe. Und wir wollen nicht, dass Fremde durch unser Land schleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38644] = { id = 38644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gehöfte", description = "Vergebt uns, <Fremder/Fremde>. Bürgermeister Heathrow stand in letzter Zeit wirklich unter sehr viel Anspannung.\n\nUnd ich kann ihn verstehen: Seine eigene Tochter, Penelope, ist seit zwei Tagen verschollen.\n\nTatsächlich fehlen uns immer noch Informationen über einige Gehöfte im Süden: das Haus von Bürgermeister Heathrow, der Hof von Muttchen Marl und die Anlegestelle der Radcliffes. Könntet Ihr vielleicht nachsehen, was dort vor sich geht?\n\nWenn Ihr uns helft, lässt sich vielleicht auch das Herz des Bürgermeisters erweichen.", sourceObjective = "Seht euch beim Haus von Bürgermeisters Heathrow, beim Hof von Muttchen Marl und bei der Angelanlegestelle der Radcliffes um.", completion = "Tut mir leid, dass ich so argwöhnisch war. Wir sind aufgrund der Angriffe in letzter Zeit alle etwas angespannt.\n\nIch bin Euch beiden sehr dankbar.\n\nDank Euch ist die Situation jetzt unter Kontrolle. Wir müssen noch viel Wiederaufbauarbeit leisten, aber wir werden überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[38645] = { id = 38645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinder der Nacht", description = "Ich bin nicht ihr Feind, aber davon wollen diese Leute nichts wissen.\n\nIhr Dorf wurde von ein paar meiner ältesten Freunde angegriffen. Freunde, die... nicht mehr am Leben sind.\n\nIch weiß nicht, unter wessen Einfluss sie jetzt stehen, aber zu Lebzeiten hätten diese edlen Soldaten niemals so gehandelt. Doch die Lösung dieses Rätsels muss vorerst warten.\n\nJetzt müssen wir erst einmal das Vertrauen der Dorfbewohner gewinnen. Schaltet die Soldaten der Rabenwehr aus, die die Dorfbewohner bedrängen.", sourceObjective = "Tötet 12 auferstandene Assassinen, Falken der Rabenwehr oder auferstandene Hunde.", completion = "Sehr gut. Diese unschuldigen Dorfbewohner haben nichts getan, das diese Angriffe rechtfertigen würde. Es war gut von Euch, ihnen zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38646] = { id = 38646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zielhilfe", description = "Seht Ihr die gefräßigen Vögel, die über meinem Gehöft kreisen? Diese widerlichen Viecher hinterlassen hier ihren Dreck und fressen meine Ernte auf.\n\nIch würde sie gern selbst mit meiner Flinte vertreiben, aber meine Augen sind nicht mehr die besten.\n\nNehmt diese Leuchtpistole und markiert sie damit für mich.\n\nWenn ich sie einmal im Visier habe, werden sie ordentlich Federn lassen!", sourceObjective = "Verwendet Muttchens Leuchtpistole, um 6 Falken der Rabenwehr zu markieren.", completion = "Denen haben wir es gezeigt, was, mein Guter? Glücklicherweise haben mich meine Adleraugen noch nicht im Stich gelassen. Ich danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[38647] = { id = 38647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet den Mais!", description = "Der Sommermais ist reif und muss schleunigst geerntet werden. Ich brauche jemanden, der mir dabei hilft, bevor die Nachtelfenräuber sich darüber hermachen.\n\nWenn Ihr ihn für mich ernten könnt, werde ich Euch fürstlich belohnen.\n\nDie Stadtbewohner brauchen Lebensmittel – und ich werde nächsten Winter auf keinen Fall wieder Ratten essen.", sourceObjective = "Sammelt 5 Getreidefässer.", progress = "Der Mais erntet sich ja nicht von selbst.", completion = "Sehr gut, diese Fässer werde ich sofort aufladen und in die Stadt bringen lassen.\n\nIch danke Euch, {name}. Damit können wir einige leere Bäuche füllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38648] = { id = 38648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle der Rabenwehr", description = "Der Brief ist mit Mitternachtstinte geschrieben:\n\n\"Eine Dämoneninvasion steht kurz bevor. Aber solange die Feuer der Rabenwehr brennen, werden wir das Land der Kaldorei beschützen. Tötet alle Eindringlinge, die sich uns entgegenstellen.\n\n- K.R.\"\n\nVielleicht solltet Ihr das Jarod Schattensang zeigen.", sourceObjective = "Kehrt zu Kommandant Jarod Schattensang in Bradenbach zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[38649] = { id = 38649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stille in der Stadt", description = "Aus Suramar vernehmen wir nur noch beunruhigende Stille.\n\nOculeth hat mir gerade mitgeteilt, dass der Teleporter zum Mondsichelforum außer Gefecht ist. Er kann Vanthir genauso wenig erreichen wie ich.\n\nIch glaube nicht unbedingt, dass etwas Schlimmes passiert ist, aber dennoch müssen wir dies untersuchen.\n\nSprecht mit Oculeth, damit er Euch zum Mondsichelforum bringt. Wir müssen herausfinden, was geschehen ist.", sourceObjective = "Sprecht mit Großtelemant Oculeth.", completion = "Irgendetwas stimmt hier nicht. Das kann ich am ganzen Körper spüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[38654] = { id = 38654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Giant Raptor" }
quests[38655] = { id = 38655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An der Wurzel packen", description = "Die gewaltigen Wurzeln von Shaladrassil verbreiten im ganzen Wald eine fürchterliche Verderbnis.\n\nWenn wir Val'sharah retten wollen, müssen wir einen Weg finden, die Ausbreitung des Weltenbaums zu unterbinden.\n\nWenn Ihr mir genug verderbte Wurzelproben bringt, werde ich versuchen, ihnen ihre Geheimnisse zu entlocken.", sourceObjective = "Sammelt 30 verderbte Wurzelproben.", progress = "Habt Ihr die Wurzelproben einsammeln können?", completion = "Es ist, wie ich befürchtet hatte, {race}. Diese Verderbnis... sie lässt sich nicht mehr umkehren.\n\nJetzt bleibt uns nur noch eins: Wir müssen einen Weg finden, ihre Quelle zu bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38656] = { id = 38656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Dämons", description = "Die dämonische Rune glüht in Eurer Hand und strahlt dunkle Macht aus. Ein einzelnes Wort in der Schrift der Dämonen leuchtet kalt auf...\n\nGRAVAX...", sourceObjective = "Bringt das dämonische Emblem zu Isoraen Nachtstern am Tempel von Elune zurück.", completion = "Ich bin beeindruckt, dass Ihr einen so mächtigen Dämon töten konntet. Wir können uns glücklich schätzen, dass Ihr auf unserer Seite kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[38657] = { id = 38657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Swamp Sword" }
quests[38662] = { id = 38662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränen der Hoffnung", description = "Die Tränen von Elune sind ein heiliges Artefakt, das seit Tausenden von Jahren von meinem Orden beschützt wird. Das erzähle ich Euch, damit Ihr die Bedeutung Eurer Aufgabe einzuschätzen versteht.\n\nAber Ysera ist edel und weise, und ich vertraue auf ihre Führung. Ihr findet die Tränen in einer Kammer am östlichen Rand des Tempelgeländes.\n\nAber seht Euch vor, denn das ganze Gebiet wurde von Dämonen überrannt.", sourceObjective = "Besorgt die Tränen von Elune.", completion = "Xavius hat unser heiliges Artefakt gestohlen?\n\nElune, vergebt mir. Ich habe versagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38663] = { id = 38663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Würfel sind gefallen", description = "Dank Eurer Hilfe ist der Tempel erst einmal sicher.\n\nAber die Tränen von Elune wurden gestohlen, und der Weltenbaum Shaladrassil, der einstige Beschützer dieser Lande, ist nun ein Instrument in den Händen unseres Feindes. Der Smaragdgrüne Traum selbst wird von einem Alptraum verschlungen.\n\nDer Mut verlässt die Herzen unseres Volkes und sein Glaube wird härter geprüft als je zuvor. Kehrt mit meinem Bericht zu Ysera zurück, {name}.\n\nIch werde mich an Elune wenden, solang es mir möglich ist. Vielleicht gibt es ja doch noch Hoffnung.", sourceObjective = "Sprecht mit Ysera im Hain des Cenarius.", completion = "Das sind schlimme Neuigkeiten, {name}.\n\nSchöpft Kraft aus Eurem Mut, denn Azeroth ist jetzt auf seine Helden angewiesen... mehr als je zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[38664] = { id = 38664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saved Family 1" }
quests[38665] = { id = 38665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saved Family 2" }
quests[38666] = { id = 38666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Eligible for Grumpy" }
quests[38668] = { id = 38668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere letzte Hoffnung", description = "Eure Wärterin Maiev Schattensang steht vor Eurer geöffneten Zellentür. Die Anführerin der Wächterinnen ist gerade damit fertig, Eure Fesseln abzunehmen.\n\nIn der Ferne hört Ihr Schlachtgetümmel. Der unverwechselbare Gestank der Brennenden Legion liegt in der Luft.", sourceObjective = "Sprecht mit Maiev Schattensang im Zellenblock der Illidari.", sourceObjectiveStatus = "unverified-source-field" }
quests[38669] = { id = 38669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere letzte Hoffnung", description = "Das Verlies wurde von der Brennenden Legion überrannt.\n\nIch ertrage es kaum, das zu sagen, doch ich fürchte das Einzige, das zwischen uns und einem grausamen Schicksal steht... seid IHR. Glaubt mir, es gibt nichts, das mir mehr widerstrebt, doch es scheint, ich habe keine Wahl.\n\nHelft mir, <Dämonenjäger/Dämonenjägerin>, und ich schenke Euch Eure Freiheit.", sourceObjective = "Beschafft Euch Eure neuen Kriegsgleven.", sourceObjectiveStatus = "unverified-source-field" }
quests[38670] = { id = 38670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goredome 2" }
quests[38671] = { id = 38671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Habseligkeiten", description = "Ist dies das Ende?\n\nUnser geliebter Malfurion. Ich sah ihn in den Klauen der Träumerin, aber Ysera war... so anders, so verderbt...\n\nShaladrassil, unser mächtiger Weltenbaum, ist bis zur Unkenntlichkeit durch die Verderbnis entstellt.\n\nWir mussten aus unserem Zuhause fliehen und unsere Habseligkeiten zurücklassen. Einige davon waren Erbstücke, die uns heilig sind. Ich bitte Euch, {class}, bringt sie mir zurück, wenn Ihr könnt.", sourceObjective = "Beschafft 5 Erbstücke aus dem Schattenmoor.", progress = "Habt Ihr die Sachen zurückholen können?", completion = "Es ist nicht viel, aber mehr, als ich erhofft hatte. Habt unseren Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[38672] = { id = 38672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch", description = "Wir können uns unseren Weg aus dem Verlies nicht ohne Hilfe freikämpfen.\n\nZwei Eurer Verbündeten werden in diesem Raum gefangen gehalten: Kayn Sonnenzorn und Altruis der Leidende.\n\nSchnell, befreit sie! Ihre Fähigkeiten sind von größtem Nutzen für uns.", sourceObjective = "Befreit Altruis den Leidenden und Kayn Sonnenzorn.", progress = "<Der Hebel scheint für die Tür gedacht zu sein.>", completion = "<Betätigt den Hebel.>", sourceObjectiveStatus = "unverified-source-field" }
quests[38675] = { id = 38675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Alptraums", description = "Ich weiß lediglich, dass mein Gatte irgendwo tiefer in diesem entstellten Wald steckt.\n\nEr ist noch am Leben, aber ob er unversehrt ist, ist ungewiss.\n\n<Tyrandes Gesichtsausdruck verhärtet sich, während sie Euch einen finsteren Blick zuwirft.>\n\nWenn er es nicht ist, wird nicht einmal Elune Xavius beschützen können.", sourceObjective = "Folgt Malfurions Pfad durch den Alptraum.", completion = "Vor dieser Verderbnis ist niemand sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[38676] = { id = 38676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 025 - Weeping Bluffs - ZTO" }
